set local lock_timeout = '5s';

-- ---- 1. Le lot, en tables temporaires -----------------------------------------------------
drop table if exists pg_temp._qdeme_modeles;
create temporary table _qdeme_modeles (
	id uuid primary key,
	branche text not null, notion text not null, sous_notion text,
	grades text[] not null,
	-- Statut relevé : les neufs en héritent (un brouillon publié depuis publierait ses neufs).
	statut text not null,
	avant jsonb not null, apres jsonb not null,
	-- Nœud d'arrivée (R2 : les points du modèle vivent ailleurs) ; null : il ne bouge pas.
	branche_apres text, notion_apres text, sous_notion_apres text
);
insert into _qdeme_modeles values ('0931c87e-2038-422e-a783-a096c3bd23e8', $qdeme$Fonctions$qdeme$, $qdeme$Fonctions trigonométriques$qdeme$, $qdeme$cosinus et sinus d'un réel$qdeme$, array['1_SPE'], 'published',
  $qdeme${"title":"Démontrer les valeurs de cos(π/3) et sin(π/3)","description":"Démonstration à trous de cos(π/3) = 1/2 et sin(π/3) = √3/2 : triangle OAM équilatéral (justification), H milieu de [OA], sinus par cos² + sin² = 1","variations":[{"statement":"Dans un repère orthonormé d'origine $O$, soit $A(1\\,;0)$ et $M$ le point du cercle trigonométrique associé au réel $\\dfrac{\\pi}{3}$. On note $H$ le projeté orthogonal de $M$ sur l'axe des abscisses : $OH=\\cos\\left(\\dfrac{\\pi}{3}\\right)$ et $HM=\\sin\\left(\\dfrac{\\pi}{3}\\right)$. L'angle $\\widehat{AOM}$ mesure $60^\\circ$.\n\nLe triangle $OAM$ est équilatéral. Pourquoi ?\n\n```choix\n- Car il est isocèle en $O$, avec un angle de $60^\\circ$ en $O$.\n- Car $OA=OM=1$.\n- Car tout triangle dont les sommets sont sur le cercle trigonométrique est équilatéral.\n- Car l'angle $\\widehat{AOM}$ est droit.\n```","variables":[],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["$OA=OM=1$ (rayons du cercle) : le triangle est isocèle en $O$, ce qui ne suffit pas.","Ses angles à la base sont égaux et valent $\\dfrac{180^\\circ-60^\\circ}{2}=60^\\circ$ : les trois angles valent $60^\\circ$, le triangle est **équilatéral**."]}},{"statement":"Dans un repère orthonormé d'origine $O$, soit $A(1\\,;0)$ et $M$ le point du cercle trigonométrique associé au réel $\\dfrac{\\pi}{3}$. On note $H$ le projeté orthogonal de $M$ sur l'axe des abscisses : $OH=\\cos\\left(\\dfrac{\\pi}{3}\\right)$ et $HM=\\sin\\left(\\dfrac{\\pi}{3}\\right)$. L'angle $\\widehat{AOM}$ mesure $60^\\circ$.\n\nLe triangle $OAM$ est équilatéral : sa hauteur issue de $M$ est aussi une médiane, donc $H$ est le milieu de $[OA]$. Complète.\n\n$\\cos\\left(\\dfrac{\\pi}{3}\\right)=?$","variables":[],"blanks":[{"expectedAnswer":"\\frac{1}{2}","acceptDecimal":true}],"correction":{"steps":["$H$ est le milieu de $[OA]$ et $OA=1$.","Donc $\\cos\\left(\\dfrac{\\pi}{3}\\right)=OH=\\textcolor{{{color:primary.0}}}{\\dfrac{1}{2}}$."]}},{"statement":"Dans un repère orthonormé d'origine $O$, soit $A(1\\,;0)$ et $M$ le point du cercle trigonométrique associé au réel $\\dfrac{\\pi}{3}$. On note $H$ le projeté orthogonal de $M$ sur l'axe des abscisses : $OH=\\cos\\left(\\dfrac{\\pi}{3}\\right)$ et $HM=\\sin\\left(\\dfrac{\\pi}{3}\\right)$. L'angle $\\widehat{AOM}$ mesure $60^\\circ$.\n\nOn a obtenu $\\cos\\left(\\dfrac{\\pi}{3}\\right)=\\dfrac{1}{2}$. On sait que $\\cos^2 x+\\sin^2 x=1$ pour tout réel $x$, et $\\sin\\left(\\dfrac{\\pi}{3}\\right)>0$ car $M$ a une ordonnée positive. Complète par la valeur exacte.\n\n$\\sin\\left(\\dfrac{\\pi}{3}\\right)=?$","variables":[],"blanks":[{"expectedAnswer":"\\frac{\\sqrt{3}}{2}"}],"correction":{"steps":["$\\sin\\left(\\dfrac{\\pi}{3}\\right)^2=1-\\left(\\dfrac{1}{2}\\right)^2=1-\\dfrac{1}{4}=\\dfrac{3}{4}$.","Le sinus est positif : $\\sin\\left(\\dfrac{\\pi}{3}\\right)=\\sqrt{\\dfrac{3}{4}}=\\textcolor{{{color:primary.0}}}{\\dfrac{\\sqrt{3}}{2}}$."]}}],"shared":{},"test_specs":[{"description":"isocèle avec un angle de 60°","variationIndex":0,"variables":{},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : isocèle seulement","variationIndex":0,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : tout triangle inscrit","variationIndex":0,"variables":{},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : angle droit","variationIndex":0,"variables":{},"answers":["3"],"expected":{"status":"incorrect"}},{"description":"1/2","variationIndex":1,"variables":{},"answers":["\\frac{1}{2}"],"expected":{"status":"correct"}},{"description":"Écriture décimale 0,5","variationIndex":1,"variables":{},"answers":["0{,}5"],"expected":{"status":"correct"}},{"description":"Erreur : √3/2","variationIndex":1,"variables":{},"answers":["\\frac{\\sqrt{3}}{2}"],"expected":{"status":"incorrect"}},{"description":"Erreur : 1","variationIndex":1,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"√3/2","variationIndex":2,"variables":{},"answers":["\\frac{\\sqrt{3}}{2}"],"expected":{"status":"correct"}},{"description":"Erreur : 3/4 (le carré)","variationIndex":2,"variables":{},"answers":["\\frac{3}{4}"],"expected":{"status":"incorrect"}},{"description":"Erreur : 1/2","variationIndex":2,"variables":{},"answers":["\\frac{1}{2}"],"expected":{"status":"incorrect"}},{"description":"Erreur : √2/2","variationIndex":2,"variables":{},"answers":["\\frac{\\sqrt{2}}{2}"],"expected":{"status":"incorrect"}},{"description":"Erreur : −√3/2","variationIndex":2,"variables":{},"answers":["-\\frac{\\sqrt{3}}{2}"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
  $qdeme${"title":"Démontrer les valeurs de cos(π/3) et sin(π/3)","description":"Démonstration à trous de cos(π/3) = 1/2 et sin(π/3) = √3/2 : triangle OAM équilatéral (justification), H milieu de [OA], sinus par cos² + sin² = 1","variations":[{"statement":"Dans un repère orthonormé d'origine $O$, soit $A(1\\,;0)$ et $M$ le point du cercle trigonométrique associé au réel $\\dfrac{\\pi}{3}$. On note $H$ le projeté orthogonal de $M$ sur l'axe des abscisses : $OH=\\cos\\left(\\dfrac{\\pi}{3}\\right)$ et $HM=\\sin\\left(\\dfrac{\\pi}{3}\\right)$. L'angle $\\widehat{AOM}$ mesure $60^\\circ$.\n\nLe triangle $OAM$ est équilatéral. Pourquoi ?\n\n```choix\n- Car il est isocèle en $O$, avec un angle de $60^\\circ$ en $O$.\n- Car $OA=OM=1$.\n- Car tout triangle dont les sommets sont sur le cercle trigonométrique est équilatéral.\n- Car l'angle $\\widehat{AOM}$ est droit.\n```","variables":[],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["$OA=OM=1$ (rayons du cercle) : le triangle est isocèle en $O$, ce qui ne suffit pas.","Ses angles à la base sont égaux et valent $\\dfrac{180^\\circ-60^\\circ}{2}=60^\\circ$ : les trois angles valent $60^\\circ$, le triangle est **équilatéral**."]}},{"statement":"Dans un repère orthonormé d'origine $O$, soit $A(1\\,;0)$ et $M$ le point du cercle trigonométrique associé au réel $\\dfrac{\\pi}{3}$. On note $H$ le projeté orthogonal de $M$ sur l'axe des abscisses : $OH=\\cos\\left(\\dfrac{\\pi}{3}\\right)$ et $HM=\\sin\\left(\\dfrac{\\pi}{3}\\right)$. L'angle $\\widehat{AOM}$ mesure $60^\\circ$.\n\nLe triangle $OAM$ est équilatéral : sa hauteur issue de $M$ est aussi une médiane, donc $H$ est le milieu de $[OA]$. Complète.\n\n$\\cos\\left(\\dfrac{\\pi}{3}\\right)=?$","variables":[],"blanks":[{"expectedAnswer":"\\frac{1}{2}","acceptDecimal":true}],"correction":{"steps":["$H$ est le milieu de $[OA]$ et $OA=1$.","Donc $\\cos\\left(\\dfrac{\\pi}{3}\\right)=OH=\\textcolor{{{color:primary.0}}}{\\dfrac{1}{2}}$."]}},{"statement":"Dans un repère orthonormé d'origine $O$, soit $A(1\\,;0)$ et $M$ le point du cercle trigonométrique associé au réel $\\dfrac{\\pi}{3}$. On note $H$ le projeté orthogonal de $M$ sur l'axe des abscisses : $OH=\\cos\\left(\\dfrac{\\pi}{3}\\right)$ et $HM=\\sin\\left(\\dfrac{\\pi}{3}\\right)$. L'angle $\\widehat{AOM}$ mesure $60^\\circ$.\n\nOn a obtenu $\\cos\\left(\\dfrac{\\pi}{3}\\right)=\\dfrac{1}{2}$. On sait que $\\cos^2 x+\\sin^2 x=1$ pour tout réel $x$, et $\\sin\\left(\\dfrac{\\pi}{3}\\right)>0$ car $M$ a une ordonnée positive. Complète par la valeur exacte.\n\n$\\sin\\left(\\dfrac{\\pi}{3}\\right)=?$","variables":[],"blanks":[{"expectedAnswer":"\\frac{\\sqrt{3}}{2}"}],"correction":{"steps":["$\\sin\\left(\\dfrac{\\pi}{3}\\right)^2=1-\\left(\\dfrac{1}{2}\\right)^2=1-\\dfrac{1}{4}=\\dfrac{3}{4}$.","Le sinus est positif : $\\sin\\left(\\dfrac{\\pi}{3}\\right)=\\sqrt{\\dfrac{3}{4}}=\\textcolor{{{color:primary.0}}}{\\dfrac{\\sqrt{3}}{2}}$."]}},{"statement":"Dans un repère orthonormé d'origine $O$, soit $A(1\\,;0)$, $M$ le point du cercle trigonométrique associé au réel $\\dfrac{\\pi}{3}$, et $H$ son projeté orthogonal sur l'axe des abscisses : $OH=\\cos\\left(\\dfrac{\\pi}{3}\\right)$, $HM=\\sin\\left(\\dfrac{\\pi}{3}\\right)$ et $\\widehat{AOM}=60^\\circ$. On démontre que $\\cos\\left(\\dfrac{\\pi}{3}\\right)=\\dfrac{1}{2}$ et $\\sin\\left(\\dfrac{\\pi}{3}\\right)=\\dfrac{\\sqrt{3}}{2}$.\n\nRemets les étapes de la démonstration dans l'ordre.\n\n```ranger\nsigne: aucun\n- $OA=OM=1$ : le triangle $OAM$ est isocèle en $O$.\n- Ses angles à la base valent $\\dfrac{180^\\circ-60^\\circ}{2}=60^\\circ$ : il est équilatéral.\n- Dans ce triangle équilatéral, la hauteur issue de $M$ est aussi une médiane : $H$ est le milieu de $[OA]$.\n- Donc $\\cos\\left(\\dfrac{\\pi}{3}\\right)=OH=\\dfrac{1}{2}$.\n- Comme $\\cos^2x+\\sin^2x=1$, $\\sin^2\\left(\\dfrac{\\pi}{3}\\right)=1-\\dfrac{1}{4}=\\dfrac{3}{4}$.\n- Le sinus est positif : $\\sin\\left(\\dfrac{\\pi}{3}\\right)=\\dfrac{\\sqrt{3}}{2}$.\n```","variables":[],"correction":{"steps":["Le triangle $OAM$ est équilatéral : le pied $H$ de sa hauteur est le milieu de $[OA]$, d'où $\\cos\\left(\\dfrac{\\pi}{3}\\right)=\\dfrac{1}{2}$.","Le sinus vient ensuite de $\\cos^2+\\sin^2=1$ : $\\textcolor{{{color:primary.0}}}{\\sin\\left(\\dfrac{\\pi}{3}\\right)=\\dfrac{\\sqrt{3}}{2}}$."]}}],"shared":{},"test_specs":[{"description":"isocèle avec un angle de 60°","variationIndex":0,"variables":{},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : isocèle seulement","variationIndex":0,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : tout triangle inscrit","variationIndex":0,"variables":{},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : angle droit","variationIndex":0,"variables":{},"answers":["3"],"expected":{"status":"incorrect"}},{"description":"1/2","variationIndex":1,"variables":{},"answers":["\\frac{1}{2}"],"expected":{"status":"correct"}},{"description":"Écriture décimale 0,5","variationIndex":1,"variables":{},"answers":["0{,}5"],"expected":{"status":"correct"}},{"description":"Erreur : √3/2","variationIndex":1,"variables":{},"answers":["\\frac{\\sqrt{3}}{2}"],"expected":{"status":"incorrect"}},{"description":"Erreur : 1","variationIndex":1,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"√3/2","variationIndex":2,"variables":{},"answers":["\\frac{\\sqrt{3}}{2}"],"expected":{"status":"correct"}},{"description":"Erreur : 3/4 (le carré)","variationIndex":2,"variables":{},"answers":["\\frac{3}{4}"],"expected":{"status":"incorrect"}},{"description":"Erreur : 1/2","variationIndex":2,"variables":{},"answers":["\\frac{1}{2}"],"expected":{"status":"incorrect"}},{"description":"Erreur : √2/2","variationIndex":2,"variables":{},"answers":["\\frac{\\sqrt{2}}{2}"],"expected":{"status":"incorrect"}},{"description":"Erreur : −√3/2","variationIndex":2,"variables":{},"answers":["-\\frac{\\sqrt{3}}{2}"],"expected":{"status":"incorrect"}},{"description":"Étapes dans l’ordre","variationIndex":3,"variables":{},"answers":["5","4","1","0","2","3"],"expected":{"status":"correct"}},{"description":"Erreur : deuxième et troisième étapes échangées","variationIndex":3,"variables":{},"answers":["5","1","4","0","2","3"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
  null, null, null);
insert into _qdeme_modeles values ('16ee6f33-695d-45c0-b6fe-deb1ae02138f', $qdeme$Fonctions$qdeme$, $qdeme$Dérivation$qdeme$, $qdeme$opérations sur les dérivées$qdeme$, array['1_SPE'], 'published',
  $qdeme${"title":"Démontrer la dérivée d'un produit","description":"Démonstration à trous de (uv)′ = u′v + uv′ (taux de variation de uv) : terme ajouté et retranché, limite du premier terme, limite du taux avec des valeurs tirées","variations":[{"statement":"Soit $u$ et $v$ deux fonctions dérivables en un réel $a$. Pour $h\\neq 0$, on étudie le taux de variation du produit $uv$ entre $a$ et $a+h$ :\n\n$$\\dfrac{u(a+h)v(a+h)-u(a)v(a)}{h}$$\n\nPour faire apparaître les taux de variation de $u$ et de $v$, on ajoute et on retranche un même terme au numérateur. Lequel ?\n\n```choix\n- $u(a)v(a+h)$\n- $u(a)v(a)$\n- $u(a+h)+v(a+h)$\n- $u'(a)v'(a)$\n```","variables":[],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["$u(a+h)v(a+h)-\\textcolor{{{color:primary.0}}}{u(a)v(a+h)}=(u(a+h)-u(a))v(a+h)$ fait apparaître le taux de $u$.","$\\textcolor{{{color:primary.0}}}{u(a)v(a+h)}-u(a)v(a)=u(a)(v(a+h)-v(a))$ fait apparaître le taux de $v$.","Ajouter et retrancher $u(a)v(a)$ ne change rien : le numérateur reste le même."]}},{"statement":"Soit $u$ et $v$ deux fonctions dérivables en un réel $a$. Pour $h\\neq 0$, on étudie le taux de variation du produit $uv$ entre $a$ et $a+h$ :\n\n$$\\dfrac{u(a+h)v(a+h)-u(a)v(a)}{h}$$\n\nOn ajoute et on retranche $u(a)v(a+h)$ au numérateur, ce qui donne\n\n$$\\dfrac{u(a+h)-u(a)}{h}\\times v(a+h)+u(a)\\times\\dfrac{v(a+h)-v(a)}{h}$$\n\nOn admet que $v(a+h)$ tend vers $v(a)$ quand $h$ tend vers $0$.\n\nQuand $h$ tend vers $0$, vers quoi tend le premier terme $\\dfrac{u(a+h)-u(a)}{h}\\times v(a+h)$ ?\n\n```choix\n- $u'(a)v(a)$\n- $u'(a)v'(a)$\n- $u(a)v(a)$\n- $u'(a)$\n```","variables":[],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["$\\dfrac{u(a+h)-u(a)}{h}$ est le taux de variation de $u$ : il tend vers $u'(a)$.","$v(a+h)$ tend vers $v(a)$ (admis).","Le produit tend donc vers $\\textcolor{{{color:primary.0}}}{u'(a)v(a)}$."]}},{"statement":"Soit $u$ et $v$ deux fonctions dérivables en un réel $a$. Pour $h\\neq 0$, on étudie le taux de variation du produit $uv$ entre $a$ et $a+h$ :\n\n$$\\dfrac{u(a+h)v(a+h)-u(a)v(a)}{h}$$\n\nOn ajoute et on retranche $u(a)v(a+h)$ au numérateur, ce qui donne\n\n$$\\dfrac{u(a+h)-u(a)}{h}\\times v(a+h)+u(a)\\times\\dfrac{v(a+h)-v(a)}{h}$$\n\nOn admet que $v(a+h)$ tend vers $v(a)$ quand $h$ tend vers $0$.\n\nOn prend $u(a)={{eval:u}}$, $u'(a)={{eval:p}}$, $v(a)={{eval:v}}$ et $v'(a)={{eval:q}}$. Complète.\n\nQuand $h$ tend vers $0$, le taux de variation de $uv$ tend vers $?$","variables":[{"name":"u","expression":"1..6"},{"name":"p","expression":"2..5"},{"name":"v","expression":"1..6"},{"name":"q","expression":"2..5"}],"blanks":[{"expectedAnswer":"{{eval:p*v+u*q}}"}],"correction":{"steps":["Le premier terme tend vers $u'(a)v(a)={{eval:p}}\\times{{eval:v}}={{eval:p*v}}$.","Le second terme tend vers $u(a)v'(a)={{eval:u}}\\times{{eval:q}}={{eval:u*q}}$.","Le taux tend donc vers ${{eval:p*v}}+{{eval:u*q}}=\\textcolor{{{color:primary.0}}}{{{eval:p*v+u*q}}}$ : $(uv)'(a)=u'(a)v(a)+u(a)v'(a)$, et non $u'(a)v'(a)$."]}}],"shared":{},"test_specs":[{"description":"u(a)v(a + h)","variationIndex":0,"variables":{},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : u(a)v(a)","variationIndex":0,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : somme","variationIndex":0,"variables":{},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : u′(a)v′(a)","variationIndex":0,"variables":{},"answers":["3"],"expected":{"status":"incorrect"}},{"description":"u′(a)v(a)","variationIndex":1,"variables":{},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : u′(a)v′(a)","variationIndex":1,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : u(a)v(a)","variationIndex":1,"variables":{},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : u′(a)","variationIndex":1,"variables":{},"answers":["3"],"expected":{"status":"incorrect"}},{"description":"22 (2 × 5 + 3 × 4)","variationIndex":2,"variables":{"u":"3","p":"2","v":"5","q":"4"},"answers":["22"],"expected":{"status":"correct"}},{"description":"Erreur : 8 (u′v′)","variationIndex":2,"variables":{"u":"3","p":"2","v":"5","q":"4"},"answers":["8"],"expected":{"status":"incorrect"}},{"description":"Erreur : 10 (u′v seulement)","variationIndex":2,"variables":{"u":"3","p":"2","v":"5","q":"4"},"answers":["10"],"expected":{"status":"incorrect"}},{"description":"Erreur : 15 (uv)","variationIndex":2,"variables":{"u":"3","p":"2","v":"5","q":"4"},"answers":["15"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
  $qdeme${"title":"Démontrer la dérivée d'un produit","description":"Démonstration à trous de (uv)′ = u′v + uv′ (taux de variation de uv) : terme ajouté et retranché, limite du premier terme, limite du taux avec des valeurs tirées","variations":[{"statement":"Soit $u$ et $v$ deux fonctions dérivables en un réel $a$. Pour $h\\neq 0$, on étudie le taux de variation du produit $uv$ entre $a$ et $a+h$ :\n\n$$\\dfrac{u(a+h)v(a+h)-u(a)v(a)}{h}$$\n\nPour faire apparaître les taux de variation de $u$ et de $v$, on ajoute et on retranche un même terme au numérateur. Lequel ?\n\n```choix\n- $u(a)v(a+h)$\n- $u(a)v(a)$\n- $u(a+h)+v(a+h)$\n- $u'(a)v'(a)$\n```","variables":[],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["$u(a+h)v(a+h)-\\textcolor{{{color:primary.0}}}{u(a)v(a+h)}=(u(a+h)-u(a))v(a+h)$ fait apparaître le taux de $u$.","$\\textcolor{{{color:primary.0}}}{u(a)v(a+h)}-u(a)v(a)=u(a)(v(a+h)-v(a))$ fait apparaître le taux de $v$.","Ajouter et retrancher $u(a)v(a)$ ne change rien : le numérateur reste le même."]}},{"statement":"Soit $u$ et $v$ deux fonctions dérivables en un réel $a$. Pour $h\\neq 0$, on étudie le taux de variation du produit $uv$ entre $a$ et $a+h$ :\n\n$$\\dfrac{u(a+h)v(a+h)-u(a)v(a)}{h}$$\n\nOn ajoute et on retranche $u(a)v(a+h)$ au numérateur, ce qui donne\n\n$$\\dfrac{u(a+h)-u(a)}{h}\\times v(a+h)+u(a)\\times\\dfrac{v(a+h)-v(a)}{h}$$\n\nOn admet que $v(a+h)$ tend vers $v(a)$ quand $h$ tend vers $0$.\n\nQuand $h$ tend vers $0$, vers quoi tend le premier terme $\\dfrac{u(a+h)-u(a)}{h}\\times v(a+h)$ ?\n\n```choix\n- $u'(a)v(a)$\n- $u'(a)v'(a)$\n- $u(a)v(a)$\n- $u'(a)$\n```","variables":[],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["$\\dfrac{u(a+h)-u(a)}{h}$ est le taux de variation de $u$ : il tend vers $u'(a)$.","$v(a+h)$ tend vers $v(a)$ (admis).","Le produit tend donc vers $\\textcolor{{{color:primary.0}}}{u'(a)v(a)}$."]}},{"statement":"Soit $u$ et $v$ deux fonctions dérivables en un réel $a$. Pour $h\\neq 0$, on étudie le taux de variation du produit $uv$ entre $a$ et $a+h$ :\n\n$$\\dfrac{u(a+h)v(a+h)-u(a)v(a)}{h}$$\n\nOn ajoute et on retranche $u(a)v(a+h)$ au numérateur, ce qui donne\n\n$$\\dfrac{u(a+h)-u(a)}{h}\\times v(a+h)+u(a)\\times\\dfrac{v(a+h)-v(a)}{h}$$\n\nOn admet que $v(a+h)$ tend vers $v(a)$ quand $h$ tend vers $0$.\n\nOn prend $u(a)={{eval:u}}$, $u'(a)={{eval:p}}$, $v(a)={{eval:v}}$ et $v'(a)={{eval:q}}$. Complète.\n\nQuand $h$ tend vers $0$, le taux de variation de $uv$ tend vers $?$","variables":[{"name":"u","expression":"1..6"},{"name":"p","expression":"2..5"},{"name":"v","expression":"1..6"},{"name":"q","expression":"2..5"}],"blanks":[{"expectedAnswer":"{{eval:p*v+u*q}}"}],"correction":{"steps":["Le premier terme tend vers $u'(a)v(a)={{eval:p}}\\times{{eval:v}}={{eval:p*v}}$.","Le second terme tend vers $u(a)v'(a)={{eval:u}}\\times{{eval:q}}={{eval:u*q}}$.","Le taux tend donc vers ${{eval:p*v}}+{{eval:u*q}}=\\textcolor{{{color:primary.0}}}{{{eval:p*v+u*q}}}$ : $(uv)'(a)=u'(a)v(a)+u(a)v'(a)$, et non $u'(a)v'(a)$."]}},{"statement":"Soit $u$ et $v$ deux fonctions dérivables en un réel $a$, et $h$ un réel non nul. On admet que $v(a+h)$ tend vers $v(a)$ quand $h$ tend vers $0$. On démontre que $(uv)'(a)=u'(a)v(a)+u(a)v'(a)$.\n\nRemets les étapes de la démonstration dans l'ordre.\n\n```ranger\nsigne: aucun\n- On ajoute et on retranche $u(a)v(a+h)$ au numérateur $u(a+h)v(a+h)-u(a)v(a)$ du taux de variation de $uv$.\n- Le numérateur s'écrit $\\big(u(a+h)-u(a)\\big)v(a+h)+u(a)\\big(v(a+h)-v(a)\\big)$.\n- Le taux vaut $\\dfrac{u(a+h)-u(a)}{h}\\times v(a+h)+u(a)\\times\\dfrac{v(a+h)-v(a)}{h}$.\n- Quand $h$ tend vers $0$, ce taux tend vers $u'(a)v(a)+u(a)v'(a)$.\n- Donc $uv$ est dérivable en $a$ et $(uv)'(a)=u'(a)v(a)+u(a)v'(a)$.\n```","variables":[],"correction":{"steps":["Le terme ajouté puis retranché permet de factoriser : apparaissent les taux de variation de $u$ et de $v$.","Ils tendent vers $u'(a)$ et $v'(a)$, et $v(a+h)$ vers $v(a)$ : $\\textcolor{{{color:primary.0}}}{(uv)'(a)=u'(a)v(a)+u(a)v'(a)}$."]}}],"shared":{},"test_specs":[{"description":"u(a)v(a + h)","variationIndex":0,"variables":{},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : u(a)v(a)","variationIndex":0,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : somme","variationIndex":0,"variables":{},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : u′(a)v′(a)","variationIndex":0,"variables":{},"answers":["3"],"expected":{"status":"incorrect"}},{"description":"u′(a)v(a)","variationIndex":1,"variables":{},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : u′(a)v′(a)","variationIndex":1,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : u(a)v(a)","variationIndex":1,"variables":{},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : u′(a)","variationIndex":1,"variables":{},"answers":["3"],"expected":{"status":"incorrect"}},{"description":"22 (2 × 5 + 3 × 4)","variationIndex":2,"variables":{"u":"3","p":"2","v":"5","q":"4"},"answers":["22"],"expected":{"status":"correct"}},{"description":"Erreur : 8 (u′v′)","variationIndex":2,"variables":{"u":"3","p":"2","v":"5","q":"4"},"answers":["8"],"expected":{"status":"incorrect"}},{"description":"Erreur : 10 (u′v seulement)","variationIndex":2,"variables":{"u":"3","p":"2","v":"5","q":"4"},"answers":["10"],"expected":{"status":"incorrect"}},{"description":"Erreur : 15 (uv)","variationIndex":2,"variables":{"u":"3","p":"2","v":"5","q":"4"},"answers":["15"],"expected":{"status":"incorrect"}},{"description":"Étapes dans l’ordre","variationIndex":3,"variables":{},"answers":["4","0","1","2","3"],"expected":{"status":"correct"}},{"description":"Erreur : deuxième et troisième étapes échangées","variationIndex":3,"variables":{},"answers":["4","1","0","2","3"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
  null, null, null);
insert into _qdeme_modeles values ('5fbb9a04-d4c3-4810-b717-075493df916b', $qdeme$Suites$qdeme$, $qdeme$Suites arithmétiques$qdeme$, $qdeme$somme des termes$qdeme$, array['1_SPE'], 'published',
  $qdeme${"title":"Démontrer la somme 1 + 2 + ⋯ + n","description":"Démonstration à trous de 1 + 2 + ⋯ + n = n(n + 1)/2 (S écrite deux fois, à l'envers) : somme d'une colonne, 2S, justification du produit n(n + 1)","variations":[{"statement":"Soit $n$ un entier naturel non nul et $S=1+2+\\cdots+n$. On écrit $S$ deux fois, la seconde dans l'ordre inverse :\n\n$$S=1+2+\\cdots+(n-1)+n$$\n\n$$S=n+(n-1)+\\cdots+2+1$$\n\npuis on additionne ces deux égalités terme à terme (le premier terme avec le premier, le deuxième avec le deuxième, etc.).\n\nLes sommes $1+n$, $2+(n-1)$, …, $n+1$ sont toutes égales. Complète.\n\nChacune vaut $?$","variables":[],"blanks":[{"expectedAnswer":"n+1"}],"correction":{"steps":["$1+n=n+1$, $2+(n-1)=n+1$, … : quand on avance d'un rang, le terme du haut augmente de $1$ et celui du bas diminue de $1$.","Chaque somme vaut donc $\\textcolor{{{color:primary.0}}}{n+1}$."]}},{"statement":"Soit $n$ un entier naturel non nul et $S=1+2+\\cdots+n$. On écrit $S$ deux fois, la seconde dans l'ordre inverse :\n\n$$S=1+2+\\cdots+(n-1)+n$$\n\n$$S=n+(n-1)+\\cdots+2+1$$\n\npuis on additionne ces deux égalités terme à terme (le premier terme avec le premier, le deuxième avec le deuxième, etc.).\n\nChacune des sommes $1+n$, $2+(n-1)$, …, $n+1$ vaut $n+1$. Complète.\n\n$2S=?$","variables":[],"blanks":[{"expectedAnswer":"n(n+1)","requiredForm":{"pattern":"u"}}],"correction":{"steps":["Il y a $n$ sommes (une par terme de $S$), chacune égale à $n+1$.","Donc $2S=\\textcolor{{{color:primary.0}}}{n(n+1)}$, et $S=\\dfrac{n(n+1)}{2}$."]}},{"statement":"Soit $n$ un entier naturel non nul et $S=1+2+\\cdots+n$. On écrit $S$ deux fois, la seconde dans l'ordre inverse :\n\n$$S=1+2+\\cdots+(n-1)+n$$\n\n$$S=n+(n-1)+\\cdots+2+1$$\n\npuis on additionne ces deux égalités terme à terme (le premier terme avec le premier, le deuxième avec le deuxième, etc.).\n\nOn obtient $2S=n(n+1)$. Pourquoi ?\n\n```choix\n- Il y a $n$ sommes de deux termes, et chacune vaut $n+1$.\n- Il y a $n+1$ sommes de deux termes, et chacune vaut $n$.\n- Il y a $n$ sommes de deux termes, et chacune vaut $n$.\n- Il y a $\\dfrac{n}{2}$ sommes de deux termes, et chacune vaut $n+1$.\n```","variables":[],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["$S$ compte $n$ termes : en les additionnant deux à deux, on obtient $\\textcolor{{{color:primary.0}}}{n}$ sommes.","Chacune vaut $\\textcolor{{{color:primary.1}}}{n+1}$ : $1+n$, $2+(n-1)$, …, $n+1$.","Donc $2S=n(n+1)$ et $S=\\dfrac{n(n+1)}{2}$. Les $\\dfrac{n}{2}$ sommes donneraient $S$, pas $2S$, et seulement si $n$ est pair."]}}],"shared":{},"test_specs":[{"description":"n + 1","variationIndex":0,"variables":{},"answers":["n+1"],"expected":{"status":"correct"}},{"description":"Erreur : n","variationIndex":0,"variables":{},"answers":["n"],"expected":{"status":"incorrect"}},{"description":"Erreur : n − 1","variationIndex":0,"variables":{},"answers":["n-1"],"expected":{"status":"incorrect"}},{"description":"n(n + 1)","variationIndex":1,"variables":{},"answers":["n(n+1)"],"expected":{"status":"correct"}},{"description":"Écriture n² + n","variationIndex":1,"variables":{},"answers":["n^2+n"],"expected":{"status":"correct"}},{"description":"Erreur : n(n + 1)/2 (S au lieu de 2S)","variationIndex":1,"variables":{},"answers":["\\frac{n(n+1)}{2}"],"expected":{"status":"incorrect"}},{"description":"Erreur : (n + 1)²","variationIndex":1,"variables":{},"answers":["(n+1)^2"],"expected":{"status":"incorrect"}},{"description":"Erreur : n²","variationIndex":1,"variables":{},"answers":["n^2"],"expected":{"status":"incorrect"}},{"description":"n sommes de n + 1","variationIndex":2,"variables":{},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : n + 1 sommes de n","variationIndex":2,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : n sommes de n","variationIndex":2,"variables":{},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : n/2 sommes","variationIndex":2,"variables":{},"answers":["3"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
  $qdeme${"title":"Démontrer la somme 1 + 2 + ⋯ + n","description":"Démonstration à trous de 1 + 2 + ⋯ + n = n(n + 1)/2 (S écrite deux fois, à l'envers) : somme d'une colonne, 2S, justification du produit n(n + 1)","variations":[{"statement":"Soit $n$ un entier naturel non nul et $S=1+2+\\cdots+n$. On écrit $S$ deux fois, la seconde dans l'ordre inverse :\n\n$$S=1+2+\\cdots+(n-1)+n$$\n\n$$S=n+(n-1)+\\cdots+2+1$$\n\npuis on additionne ces deux égalités terme à terme (le premier terme avec le premier, le deuxième avec le deuxième, etc.).\n\nLes sommes $1+n$, $2+(n-1)$, …, $n+1$ sont toutes égales. Complète.\n\nChacune vaut $?$","variables":[],"blanks":[{"expectedAnswer":"n+1"}],"correction":{"steps":["$1+n=n+1$, $2+(n-1)=n+1$, … : quand on avance d'un rang, le terme du haut augmente de $1$ et celui du bas diminue de $1$.","Chaque somme vaut donc $\\textcolor{{{color:primary.0}}}{n+1}$."]}},{"statement":"Soit $n$ un entier naturel non nul et $S=1+2+\\cdots+n$. On écrit $S$ deux fois, la seconde dans l'ordre inverse :\n\n$$S=1+2+\\cdots+(n-1)+n$$\n\n$$S=n+(n-1)+\\cdots+2+1$$\n\npuis on additionne ces deux égalités terme à terme (le premier terme avec le premier, le deuxième avec le deuxième, etc.).\n\nChacune des sommes $1+n$, $2+(n-1)$, …, $n+1$ vaut $n+1$. Complète.\n\n$2S=?$","variables":[],"blanks":[{"expectedAnswer":"n(n+1)","requiredForm":{"pattern":"u"}}],"correction":{"steps":["Il y a $n$ sommes (une par terme de $S$), chacune égale à $n+1$.","Donc $2S=\\textcolor{{{color:primary.0}}}{n(n+1)}$, et $S=\\dfrac{n(n+1)}{2}$."]}},{"statement":"Soit $n$ un entier naturel non nul et $S=1+2+\\cdots+n$. On écrit $S$ deux fois, la seconde dans l'ordre inverse :\n\n$$S=1+2+\\cdots+(n-1)+n$$\n\n$$S=n+(n-1)+\\cdots+2+1$$\n\npuis on additionne ces deux égalités terme à terme (le premier terme avec le premier, le deuxième avec le deuxième, etc.).\n\nOn obtient $2S=n(n+1)$. Pourquoi ?\n\n```choix\n- Il y a $n$ sommes de deux termes, et chacune vaut $n+1$.\n- Il y a $n+1$ sommes de deux termes, et chacune vaut $n$.\n- Il y a $n$ sommes de deux termes, et chacune vaut $n$.\n- Il y a $\\dfrac{n}{2}$ sommes de deux termes, et chacune vaut $n+1$.\n```","variables":[],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["$S$ compte $n$ termes : en les additionnant deux à deux, on obtient $\\textcolor{{{color:primary.0}}}{n}$ sommes.","Chacune vaut $\\textcolor{{{color:primary.1}}}{n+1}$ : $1+n$, $2+(n-1)$, …, $n+1$.","Donc $2S=n(n+1)$ et $S=\\dfrac{n(n+1)}{2}$. Les $\\dfrac{n}{2}$ sommes donneraient $S$, pas $2S$, et seulement si $n$ est pair."]}},{"statement":"Soit $n$ un entier naturel non nul et $S=1+2+\\cdots+n$. On démontre que $S=\\dfrac{n(n+1)}{2}$. On écrit $S$ deux fois, la seconde dans l'ordre inverse :\n\n$$S=1+2+\\cdots+(n-1)+n$$\n\n$$S=n+(n-1)+\\cdots+2+1$$\n\nRemets les étapes de la démonstration dans l'ordre.\n\n```ranger\nsigne: aucun\n- On additionne ces deux égalités terme à terme : $2S=(1+n)+(2+(n-1))+\\cdots+(n+1)$.\n- Chacune de ces sommes vaut $n+1$.\n- Il y a $n$ sommes, donc $2S=n(n+1)$.\n- Donc $S=\\dfrac{n(n+1)}{2}$.\n```","variables":[],"correction":{"steps":["L'addition terme à terme donne $n$ sommes de deux termes, toutes égales à $n+1$.","Donc $2S=n(n+1)$ et $\\textcolor{{{color:primary.0}}}{S=\\dfrac{n(n+1)}{2}}$."]}}],"shared":{},"test_specs":[{"description":"n + 1","variationIndex":0,"variables":{},"answers":["n+1"],"expected":{"status":"correct"}},{"description":"Erreur : n","variationIndex":0,"variables":{},"answers":["n"],"expected":{"status":"incorrect"}},{"description":"Erreur : n − 1","variationIndex":0,"variables":{},"answers":["n-1"],"expected":{"status":"incorrect"}},{"description":"n(n + 1)","variationIndex":1,"variables":{},"answers":["n(n+1)"],"expected":{"status":"correct"}},{"description":"Écriture n² + n","variationIndex":1,"variables":{},"answers":["n^2+n"],"expected":{"status":"correct"}},{"description":"Erreur : n(n + 1)/2 (S au lieu de 2S)","variationIndex":1,"variables":{},"answers":["\\frac{n(n+1)}{2}"],"expected":{"status":"incorrect"}},{"description":"Erreur : (n + 1)²","variationIndex":1,"variables":{},"answers":["(n+1)^2"],"expected":{"status":"incorrect"}},{"description":"Erreur : n²","variationIndex":1,"variables":{},"answers":["n^2"],"expected":{"status":"incorrect"}},{"description":"n sommes de n + 1","variationIndex":2,"variables":{},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : n + 1 sommes de n","variationIndex":2,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : n sommes de n","variationIndex":2,"variables":{},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : n/2 sommes","variationIndex":2,"variables":{},"answers":["3"],"expected":{"status":"incorrect"}},{"description":"Étapes dans l’ordre","variationIndex":3,"variables":{},"answers":["3","0","1","2"],"expected":{"status":"correct"}},{"description":"Erreur : deuxième et troisième étapes échangées","variationIndex":3,"variables":{},"answers":["3","1","0","2"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
  null, null, null);
insert into _qdeme_modeles values ('66ecbb33-60fc-46a9-bdfe-2a978c5dec47', $qdeme$Fonctions$qdeme$, $qdeme$Fonctions trigonométriques$qdeme$, $qdeme$cosinus et sinus d'un réel$qdeme$, array['1_SPE'], 'published',
  $qdeme${"title":"Démontrer les valeurs de cos(π/4) et sin(π/4)","description":"Démonstration à trous de cos(π/4) = sin(π/4) = √2/2 : triangle OHM rectangle isocèle (justification), cos²(π/4) = 1/2, valeur exacte positive","variations":[{"statement":"Dans un repère orthonormé d'origine $O$, soit $M$ le point du cercle trigonométrique associé au réel $\\dfrac{\\pi}{4}$, et $H$ son projeté orthogonal sur l'axe des abscisses. Ainsi $OH=\\cos\\left(\\dfrac{\\pi}{4}\\right)$, $HM=\\sin\\left(\\dfrac{\\pi}{4}\\right)$, et l'angle $\\widehat{HOM}$ mesure $45^\\circ$.\n\nOn en déduit que $\\cos\\left(\\dfrac{\\pi}{4}\\right)=\\sin\\left(\\dfrac{\\pi}{4}\\right)$. Pourquoi ?\n\n```choix\n- Car le triangle $OHM$ est rectangle isocèle en $H$.\n- Car $\\cos x=\\sin x$ pour tout réel $x$.\n- Car le cercle trigonométrique a pour rayon $1$.\n- Car $\\dfrac{\\pi}{4}$ est plus petit que $\\dfrac{\\pi}{2}$.\n```","variables":[],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["Dans le triangle $OHM$ rectangle en $H$, les angles aigus sont complémentaires : $\\widehat{OMH}=90^\\circ-45^\\circ=45^\\circ$.","Deux angles égaux : le triangle est isocèle en $H$, donc $OH=HM$, c'est-à-dire $\\textcolor{{{color:primary.0}}}{\\cos\\left(\\dfrac{\\pi}{4}\\right)=\\sin\\left(\\dfrac{\\pi}{4}\\right)}$.","En général, $\\cos x\\neq\\sin x$ : par exemple $\\cos(0)=1$ et $\\sin(0)=0$."]}},{"statement":"Dans un repère orthonormé d'origine $O$, soit $M$ le point du cercle trigonométrique associé au réel $\\dfrac{\\pi}{4}$, et $H$ son projeté orthogonal sur l'axe des abscisses. Ainsi $OH=\\cos\\left(\\dfrac{\\pi}{4}\\right)$, $HM=\\sin\\left(\\dfrac{\\pi}{4}\\right)$, et l'angle $\\widehat{HOM}$ mesure $45^\\circ$.\n\nOn sait que $\\cos\\left(\\dfrac{\\pi}{4}\\right)=\\sin\\left(\\dfrac{\\pi}{4}\\right)$, et que $\\cos^2 x+\\sin^2 x=1$ pour tout réel $x$. On note $c=\\cos\\left(\\dfrac{\\pi}{4}\\right)$, donc $c^2+c^2=1$. Complète.\n\n$c^2=?$","variables":[],"blanks":[{"expectedAnswer":"\\frac{1}{2}","acceptDecimal":true}],"correction":{"steps":["$c^2+c^2=2c^2$, donc $2c^2=1$.","Donc $c^2=\\textcolor{{{color:primary.0}}}{\\dfrac{1}{2}}$."]}},{"statement":"Dans un repère orthonormé d'origine $O$, soit $M$ le point du cercle trigonométrique associé au réel $\\dfrac{\\pi}{4}$, et $H$ son projeté orthogonal sur l'axe des abscisses. Ainsi $OH=\\cos\\left(\\dfrac{\\pi}{4}\\right)$, $HM=\\sin\\left(\\dfrac{\\pi}{4}\\right)$, et l'angle $\\widehat{HOM}$ mesure $45^\\circ$.\n\nOn a obtenu $\\cos\\left(\\dfrac{\\pi}{4}\\right)^2=\\dfrac{1}{2}$. Comme $M$ a une abscisse positive, $\\cos\\left(\\dfrac{\\pi}{4}\\right)>0$. Complète par la valeur exacte.\n\n$\\cos\\left(\\dfrac{\\pi}{4}\\right)=?$","variables":[],"blanks":[{"expectedAnswer":"\\frac{\\sqrt{2}}{2}"}],"correction":{"steps":["Le nombre positif dont le carré vaut $\\dfrac{1}{2}$ est $\\sqrt{\\dfrac{1}{2}}=\\dfrac{1}{\\sqrt{2}}=\\dfrac{\\sqrt{2}}{2}$.","Donc $\\cos\\left(\\dfrac{\\pi}{4}\\right)=\\sin\\left(\\dfrac{\\pi}{4}\\right)=\\textcolor{{{color:primary.0}}}{\\dfrac{\\sqrt{2}}{2}}$."]}}],"shared":{},"test_specs":[{"description":"triangle rectangle isocèle","variationIndex":0,"variables":{},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : cos = sin toujours","variationIndex":0,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : rayon 1","variationIndex":0,"variables":{},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : π/4 < π/2","variationIndex":0,"variables":{},"answers":["3"],"expected":{"status":"incorrect"}},{"description":"1/2","variationIndex":1,"variables":{},"answers":["\\frac{1}{2}"],"expected":{"status":"correct"}},{"description":"Écriture décimale 0,5","variationIndex":1,"variables":{},"answers":["0{,}5"],"expected":{"status":"correct"}},{"description":"Erreur : 2","variationIndex":1,"variables":{},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : 1","variationIndex":1,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : √2/2 (la valeur au lieu du carré)","variationIndex":1,"variables":{},"answers":["\\frac{\\sqrt{2}}{2}"],"expected":{"status":"incorrect"}},{"description":"√2/2","variationIndex":2,"variables":{},"answers":["\\frac{\\sqrt{2}}{2}"],"expected":{"status":"correct"}},{"description":"Forme 1/√2 : dénominateur à rendre rationnel","variationIndex":2,"variables":{},"answers":["\\frac{1}{\\sqrt{2}}"],"expected":{"status":"bad_form","constraintViolations":["form"]}},{"description":"Erreur : 1/2","variationIndex":2,"variables":{},"answers":["\\frac{1}{2}"],"expected":{"status":"incorrect"}},{"description":"Erreur : −√2/2","variationIndex":2,"variables":{},"answers":["-\\frac{\\sqrt{2}}{2}"],"expected":{"status":"incorrect"}},{"description":"Erreur : √3/2","variationIndex":2,"variables":{},"answers":["\\frac{\\sqrt{3}}{2}"],"expected":{"status":"incorrect"}},{"description":"Erreur : √2","variationIndex":2,"variables":{},"answers":["\\sqrt{2}"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
  $qdeme${"title":"Démontrer les valeurs de cos(π/4) et sin(π/4)","description":"Démonstration à trous de cos(π/4) = sin(π/4) = √2/2 : triangle OHM rectangle isocèle (justification), cos²(π/4) = 1/2, valeur exacte positive","variations":[{"statement":"Dans un repère orthonormé d'origine $O$, soit $M$ le point du cercle trigonométrique associé au réel $\\dfrac{\\pi}{4}$, et $H$ son projeté orthogonal sur l'axe des abscisses. Ainsi $OH=\\cos\\left(\\dfrac{\\pi}{4}\\right)$, $HM=\\sin\\left(\\dfrac{\\pi}{4}\\right)$, et l'angle $\\widehat{HOM}$ mesure $45^\\circ$.\n\nOn en déduit que $\\cos\\left(\\dfrac{\\pi}{4}\\right)=\\sin\\left(\\dfrac{\\pi}{4}\\right)$. Pourquoi ?\n\n```choix\n- Car le triangle $OHM$ est rectangle isocèle en $H$.\n- Car $\\cos x=\\sin x$ pour tout réel $x$.\n- Car le cercle trigonométrique a pour rayon $1$.\n- Car $\\dfrac{\\pi}{4}$ est plus petit que $\\dfrac{\\pi}{2}$.\n```","variables":[],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["Dans le triangle $OHM$ rectangle en $H$, les angles aigus sont complémentaires : $\\widehat{OMH}=90^\\circ-45^\\circ=45^\\circ$.","Deux angles égaux : le triangle est isocèle en $H$, donc $OH=HM$, c'est-à-dire $\\textcolor{{{color:primary.0}}}{\\cos\\left(\\dfrac{\\pi}{4}\\right)=\\sin\\left(\\dfrac{\\pi}{4}\\right)}$.","En général, $\\cos x\\neq\\sin x$ : par exemple $\\cos(0)=1$ et $\\sin(0)=0$."]}},{"statement":"Dans un repère orthonormé d'origine $O$, soit $M$ le point du cercle trigonométrique associé au réel $\\dfrac{\\pi}{4}$, et $H$ son projeté orthogonal sur l'axe des abscisses. Ainsi $OH=\\cos\\left(\\dfrac{\\pi}{4}\\right)$, $HM=\\sin\\left(\\dfrac{\\pi}{4}\\right)$, et l'angle $\\widehat{HOM}$ mesure $45^\\circ$.\n\nOn sait que $\\cos\\left(\\dfrac{\\pi}{4}\\right)=\\sin\\left(\\dfrac{\\pi}{4}\\right)$, et que $\\cos^2 x+\\sin^2 x=1$ pour tout réel $x$. On note $c=\\cos\\left(\\dfrac{\\pi}{4}\\right)$, donc $c^2+c^2=1$. Complète.\n\n$c^2=?$","variables":[],"blanks":[{"expectedAnswer":"\\frac{1}{2}","acceptDecimal":true}],"correction":{"steps":["$c^2+c^2=2c^2$, donc $2c^2=1$.","Donc $c^2=\\textcolor{{{color:primary.0}}}{\\dfrac{1}{2}}$."]}},{"statement":"Dans un repère orthonormé d'origine $O$, soit $M$ le point du cercle trigonométrique associé au réel $\\dfrac{\\pi}{4}$, et $H$ son projeté orthogonal sur l'axe des abscisses. Ainsi $OH=\\cos\\left(\\dfrac{\\pi}{4}\\right)$, $HM=\\sin\\left(\\dfrac{\\pi}{4}\\right)$, et l'angle $\\widehat{HOM}$ mesure $45^\\circ$.\n\nOn a obtenu $\\cos\\left(\\dfrac{\\pi}{4}\\right)^2=\\dfrac{1}{2}$. Comme $M$ a une abscisse positive, $\\cos\\left(\\dfrac{\\pi}{4}\\right)>0$. Complète par la valeur exacte.\n\n$\\cos\\left(\\dfrac{\\pi}{4}\\right)=?$","variables":[],"blanks":[{"expectedAnswer":"\\frac{\\sqrt{2}}{2}"}],"correction":{"steps":["Le nombre positif dont le carré vaut $\\dfrac{1}{2}$ est $\\sqrt{\\dfrac{1}{2}}=\\dfrac{1}{\\sqrt{2}}=\\dfrac{\\sqrt{2}}{2}$.","Donc $\\cos\\left(\\dfrac{\\pi}{4}\\right)=\\sin\\left(\\dfrac{\\pi}{4}\\right)=\\textcolor{{{color:primary.0}}}{\\dfrac{\\sqrt{2}}{2}}$."]}},{"statement":"Dans un repère orthonormé d'origine $O$, soit $M$ le point du cercle trigonométrique associé au réel $\\dfrac{\\pi}{4}$, et $H$ son projeté orthogonal sur l'axe des abscisses : $OH=\\cos\\left(\\dfrac{\\pi}{4}\\right)$, $HM=\\sin\\left(\\dfrac{\\pi}{4}\\right)$ et $\\widehat{HOM}=45^\\circ$. On démontre que $\\cos\\left(\\dfrac{\\pi}{4}\\right)=\\sin\\left(\\dfrac{\\pi}{4}\\right)=\\dfrac{\\sqrt{2}}{2}$.\n\nRemets les étapes de la démonstration dans l'ordre.\n\n```ranger\nsigne: aucun\n- Le triangle $OHM$ est rectangle en $H$, donc $\\widehat{OMH}=90^\\circ-45^\\circ=45^\\circ$.\n- Il a deux angles égaux : il est isocèle en $H$, et $\\cos\\left(\\dfrac{\\pi}{4}\\right)=\\sin\\left(\\dfrac{\\pi}{4}\\right)$.\n- On note $c$ cette valeur commune. Comme $OM=1$, le théorème de Pythagore donne $c^2+c^2=1$.\n- Donc $c^2=\\dfrac{1}{2}$.\n- Comme $c>0$, $c=\\dfrac{\\sqrt{2}}{2}$.\n```","variables":[],"correction":{"steps":["Le triangle $OHM$ est rectangle isocèle : cosinus et sinus sont égaux, et Pythagore donne $2c^2=1$.","$c$ est positif : $\\textcolor{{{color:primary.0}}}{c=\\dfrac{\\sqrt{2}}{2}}$."]}}],"shared":{},"test_specs":[{"description":"triangle rectangle isocèle","variationIndex":0,"variables":{},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : cos = sin toujours","variationIndex":0,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : rayon 1","variationIndex":0,"variables":{},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : π/4 < π/2","variationIndex":0,"variables":{},"answers":["3"],"expected":{"status":"incorrect"}},{"description":"1/2","variationIndex":1,"variables":{},"answers":["\\frac{1}{2}"],"expected":{"status":"correct"}},{"description":"Écriture décimale 0,5","variationIndex":1,"variables":{},"answers":["0{,}5"],"expected":{"status":"correct"}},{"description":"Erreur : 2","variationIndex":1,"variables":{},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : 1","variationIndex":1,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : √2/2 (la valeur au lieu du carré)","variationIndex":1,"variables":{},"answers":["\\frac{\\sqrt{2}}{2}"],"expected":{"status":"incorrect"}},{"description":"√2/2","variationIndex":2,"variables":{},"answers":["\\frac{\\sqrt{2}}{2}"],"expected":{"status":"correct"}},{"description":"Forme 1/√2 : dénominateur à rendre rationnel","variationIndex":2,"variables":{},"answers":["\\frac{1}{\\sqrt{2}}"],"expected":{"status":"bad_form","constraintViolations":["form"]}},{"description":"Erreur : 1/2","variationIndex":2,"variables":{},"answers":["\\frac{1}{2}"],"expected":{"status":"incorrect"}},{"description":"Erreur : −√2/2","variationIndex":2,"variables":{},"answers":["-\\frac{\\sqrt{2}}{2}"],"expected":{"status":"incorrect"}},{"description":"Erreur : √3/2","variationIndex":2,"variables":{}