insert into _qdeme_modeles values ('9e377c97-6940-48c9-9442-d64f05cb9a94', $qdeme$Fonctions$qdeme$, $qdeme$Dérivation$qdeme$, $qdeme$tangente$qdeme$, array['1_SPE'], 'published',
  $qdeme${"title":"Démontrer l'équation de la tangente","description":"Démonstration à trous de y = f(a) + f′(a)(x − a) : justification du coefficient directeur f′(a), ordonnée à l'origine par le point A (valeurs tirées), factorisation par f′(a)","variations":[{"statement":"Soit $f$ une fonction dérivable en $a={{eval:a}}$, avec $f({{eval:a}})={{eval:b}}$ et $f'({{eval:a}})={{eval:m}}$. On note $A$ le point de sa courbe d'abscisse ${{eval:a}}$ : $A({{eval:a}}\\,;\\,{{eval:b}})$. On cherche une équation de la tangente $T$ à la courbe en $A$.\n\nLa tangente $T$ a pour coefficient directeur ${{eval:m}}$. Pourquoi ?\n\n```choix\n- Par définition, la tangente en $A$ est la droite qui passe par $A$ et dont le coefficient directeur est le nombre dérivé $f'({{eval:a}})$.\n- Car $T$ passe par l'origine du repère.\n- Car toute droite qui passe par $A$ a ce coefficient directeur.\n- Car $f({{eval:a}})={{eval:b}}$.\n```","variables":[{"name":"a","expression":"1..6"},{"name":"b","expression":"1..9"},{"name":"m","expression":"2..6"}],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["Le nombre dérivé $f'({{eval:a}})$ est **par définition** le coefficient directeur de la tangente en $A$ : ici $\\textcolor{{{color:primary.0}}}{{{eval:m}}}$.","Une infinité de droites passent par $A$ ; la tangente est celle de coefficient directeur $f'({{eval:a}})$.","$f({{eval:a}})={{eval:b}}$ donne l'ordonnée de $A$, pas le coefficient directeur."]}},{"statement":"Soit $f$ une fonction dérivable en $a={{eval:a}}$, avec $f({{eval:a}})={{eval:b}}$ et $f'({{eval:a}})={{eval:m}}$. On note $A$ le point de sa courbe d'abscisse ${{eval:a}}$ : $A({{eval:a}}\\,;\\,{{eval:b}})$. On cherche une équation de la tangente $T$ à la courbe en $A$.\n\nLe coefficient directeur de $T$ est $f'({{eval:a}})={{eval:m}}$ : $T$ a une équation de la forme $y={{eval:m}}x+p$. Comme $A$ est sur $T$, ses coordonnées vérifient cette équation. Complète.\n\n$p=?$","variables":[{"name":"a","expression":"1..6"},{"name":"b","expression":"1..9"},{"name":"m","expression":"2..6"}],"blanks":[{"expectedAnswer":"{{eval:b-m*a}}"}],"correction":{"steps":["$A({{eval:a}}\\,;\\,{{eval:b}})$ est sur $T$ : ${{eval:b}}={{eval:m}}\\times{{eval:a}}+p$.","Donc $p={{eval:b}}-{{eval:m*a}}=\\textcolor{{{color:primary.0}}}{{{eval:b-m*a}}}$, et $T$ a pour équation $y={{eval:m}}x+({{eval:b-m*a}})$."]}},{"statement":"Soit $f$ une fonction dérivable en un réel $a$, et $A(a\\,;\\,f(a))$ le point de sa courbe d'abscisse $a$. La tangente en $A$ a pour coefficient directeur $f'(a)$ : elle a une équation de la forme $y=f'(a)x+p$.\n\nComme $A$ est sur la tangente, $f(a)=f'(a)\\times a+p$, donc $p=f(a)-f'(a)\\times a$. On remplace $p$, puis on factorise par $f'(a)$. Complète.\n\n$y=f'(a)x+f(a)-f'(a)\\times a=f(a)+f'(a)\\times(?)$","variables":[],"blanks":[{"expectedAnswer":"x-a"}],"correction":{"steps":["$f'(a)x-f'(a)\\times a=f'(a)\\times(x-a)$ : on met $f'(a)$ en facteur.","Donc $y=f(a)+f'(a)(\\textcolor{{{color:primary.0}}}{x-a})$."]}}],"shared":{},"test_specs":[{"description":"définition de la tangente","variationIndex":0,"variables":{"a":"2","b":"5","m":"3"},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : origine","variationIndex":0,"variables":{"a":"2","b":"5","m":"3"},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : toute droite par A","variationIndex":0,"variables":{"a":"2","b":"5","m":"3"},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : f(a)","variationIndex":0,"variables":{"a":"2","b":"5","m":"3"},"answers":["3"],"expected":{"status":"incorrect"}},{"description":"−1","variationIndex":1,"variables":{"a":"2","b":"5","m":"3"},"answers":["-1"],"expected":{"status":"correct"}},{"description":"Erreur : 11 (5 + 3 × 2)","variationIndex":1,"variables":{"a":"2","b":"5","m":"3"},"answers":["11"],"expected":{"status":"incorrect"}},{"description":"Erreur : 5 (f(a))","variationIndex":1,"variables":{"a":"2","b":"5","m":"3"},"answers":["5"],"expected":{"status":"incorrect"}},{"description":"Erreur : 1 (5 − 2 × 2)","variationIndex":1,"variables":{"a":"2","b":"5","m":"3"},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"x − a","variationIndex":2,"variables":{},"answers":["x-a"],"expected":{"status":"correct"}},{"description":"Erreur : a − x","variationIndex":2,"variables":{},"answers":["a-x"],"expected":{"status":"incorrect"}},{"description":"Erreur : x + a","variationIndex":2,"variables":{},"answers":["x+a"],"expected":{"status":"incorrect"}},{"description":"Erreur : x","variationIndex":2,"variables":{},"answers":["x"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
  $qdeme${"title":"Démontrer l'équation de la tangente","description":"Démonstration à trous de y = f(a) + f′(a)(x − a) : justification du coefficient directeur f′(a), ordonnée à l'origine par le point A (valeurs tirées), factorisation par f′(a)","variations":[{"statement":"Soit $f$ une fonction dérivable en $a={{eval:a}}$, avec $f({{eval:a}})={{eval:b}}$ et $f'({{eval:a}})={{eval:m}}$. On note $A$ le point de sa courbe d'abscisse ${{eval:a}}$ : $A({{eval:a}}\\,;\\,{{eval:b}})$. On cherche une équation de la tangente $T$ à la courbe en $A$.\n\nLa tangente $T$ a pour coefficient directeur ${{eval:m}}$. Pourquoi ?\n\n```choix\n- Par définition, la tangente en $A$ est la droite qui passe par $A$ et dont le coefficient directeur est le nombre dérivé $f'({{eval:a}})$.\n- Car $T$ passe par l'origine du repère.\n- Car toute droite qui passe par $A$ a ce coefficient directeur.\n- Car $f({{eval:a}})={{eval:b}}$.\n```","variables":[{"name":"a","expression":"1..6"},{"name":"b","expression":"1..9"},{"name":"m","expression":"2..6"}],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["Le nombre dérivé $f'({{eval:a}})$ est **par définition** le coefficient directeur de la tangente en $A$ : ici $\\textcolor{{{color:primary.0}}}{{{eval:m}}}$.","Une infinité de droites passent par $A$ ; la tangente est celle de coefficient directeur $f'({{eval:a}})$.","$f({{eval:a}})={{eval:b}}$ donne l'ordonnée de $A$, pas le coefficient directeur."]}},{"statement":"Soit $f$ une fonction dérivable en $a={{eval:a}}$, avec $f({{eval:a}})={{eval:b}}$ et $f'({{eval:a}})={{eval:m}}$. On note $A$ le point de sa courbe d'abscisse ${{eval:a}}$ : $A({{eval:a}}\\,;\\,{{eval:b}})$. On cherche une équation de la tangente $T$ à la courbe en $A$.\n\nLe coefficient directeur de $T$ est $f'({{eval:a}})={{eval:m}}$ : $T$ a une équation de la forme $y={{eval:m}}x+p$. Comme $A$ est sur $T$, ses coordonnées vérifient cette équation. Complète.\n\n$p=?$","variables":[{"name":"a","expression":"1..6"},{"name":"b","expression":"1..9"},{"name":"m","expression":"2..6"}],"blanks":[{"expectedAnswer":"{{eval:b-m*a}}"}],"correction":{"steps":["$A({{eval:a}}\\,;\\,{{eval:b}})$ est sur $T$ : ${{eval:b}}={{eval:m}}\\times{{eval:a}}+p$.","Donc $p={{eval:b}}-{{eval:m*a}}=\\textcolor{{{color:primary.0}}}{{{eval:b-m*a}}}$, et $T$ a pour équation $y={{eval:m}}x+({{eval:b-m*a}})$."]}},{"statement":"Soit $f$ une fonction dérivable en un réel $a$, et $A(a\\,;\\,f(a))$ le point de sa courbe d'abscisse $a$. La tangente en $A$ a pour coefficient directeur $f'(a)$ : elle a une équation de la forme $y=f'(a)x+p$.\n\nComme $A$ est sur la tangente, $f(a)=f'(a)\\times a+p$, donc $p=f(a)-f'(a)\\times a$. On remplace $p$, puis on factorise par $f'(a)$. Complète.\n\n$y=f'(a)x+f(a)-f'(a)\\times a=f(a)+f'(a)\\times(?)$","variables":[],"blanks":[{"expectedAnswer":"x-a"}],"correction":{"steps":["$f'(a)x-f'(a)\\times a=f'(a)\\times(x-a)$ : on met $f'(a)$ en facteur.","Donc $y=f(a)+f'(a)(\\textcolor{{{color:primary.0}}}{x-a})$."]}},{"statement":"Soit $f$ une fonction dérivable en un réel $a$, et $A(a\\,;f(a))$ le point de sa courbe d'abscisse $a$. On démontre que la tangente $T$ à la courbe en $A$ a pour équation $y=f(a)+f'(a)(x-a)$.\n\nRemets les étapes de la démonstration dans l'ordre.\n\n```ranger\nsigne: aucun\n- $T$ a pour coefficient directeur $f'(a)$ : elle a une équation de la forme $y=f'(a)x+p$.\n- $A(a\\,;f(a))$ est sur $T$ : $f(a)=f'(a)\\times a+p$.\n- Donc $p=f(a)-f'(a)\\times a$.\n- $T$ a pour équation $y=f'(a)x+f(a)-f'(a)\\times a$.\n- Soit $y=f(a)+f'(a)(x-a)$.\n```","variables":[],"correction":{"steps":["Le coefficient directeur vient de la définition de la tangente ; l'ordonnée à l'origine $p$, du point $A$.","On remplace $p$, puis on met $f'(a)$ en facteur : $\\textcolor{{{color:primary.0}}}{y=f(a)+f'(a)(x-a)}$."]}}],"shared":{},"test_specs":[{"description":"définition de la tangente","variationIndex":0,"variables":{"a":"2","b":"5","m":"3"},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : origine","variationIndex":0,"variables":{"a":"2","b":"5","m":"3"},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : toute droite par A","variationIndex":0,"variables":{"a":"2","b":"5","m":"3"},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : f(a)","variationIndex":0,"variables":{"a":"2","b":"5","m":"3"},"answers":["3"],"expected":{"status":"incorrect"}},{"description":"−1","variationIndex":1,"variables":{"a":"2","b":"5","m":"3"},"answers":["-1"],"expected":{"status":"correct"}},{"description":"Erreur : 11 (5 + 3 × 2)","variationIndex":1,"variables":{"a":"2","b":"5","m":"3"},"answers":["11"],"expected":{"status":"incorrect"}},{"description":"Erreur : 5 (f(a))","variationIndex":1,"variables":{"a":"2","b":"5","m":"3"},"answers":["5"],"expected":{"status":"incorrect"}},{"description":"Erreur : 1 (5 − 2 × 2)","variationIndex":1,"variables":{"a":"2","b":"5","m":"3"},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"x − a","variationIndex":2,"variables":{},"answers":["x-a"],"expected":{"status":"correct"}},{"description":"Erreur : a − x","variationIndex":2,"variables":{},"answers":["a-x"],"expected":{"status":"incorrect"}},{"description":"Erreur : x + a","variationIndex":2,"variables":{},"answers":["x+a"],"expected":{"status":"incorrect"}},{"description":"Erreur : x","variationIndex":2,"variables":{},"answers":["x"],"expected":{"status":"incorrect"}},{"description":"Étapes dans l’ordre","variationIndex":3,"variables":{},"answers":["4","0","1","2","3"],"expected":{"status":"correct"}},{"description":"Erreur : deuxième et troisième étapes échangées","variationIndex":3,"variables":{},"answers":["4","1","0","2","3"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
  null, null, null);
insert into _qdeme_modeles values ('a81c4c9f-7a25-48a4-89c4-d48cadf0fa1b', $qdeme$Suites$qdeme$, $qdeme$Suites arithmétiques$qdeme$, $qdeme$terme général$qdeme$, array['1_SPE'], 'published',
  $qdeme${"title":"Démontrer le terme général d'une suite arithmétique","description":"Démonstration à trous de uₙ = u₀ + nr (somme télescopique des n égalités uₖ₊₁ − uₖ = r) : uₙ − u₀ à compléter, nombre de termes de la somme, justification du télescopage","variations":[{"statement":"Soit $(u_n)$ la suite arithmétique de premier terme $u_0={{eval:a}}$ et de raison ${{eval:r}}$. On cherche l'expression de $u_n$ en fonction de $n$, pour tout entier naturel $n$ non nul.\n\nPour tout entier naturel $k$, $u_{k+1}-u_k={{eval:r}}$. On écrit cette égalité pour $k=0$, $k=1$, …, $k=n-1$, puis on additionne membre à membre :\n\n$$(u_1-u_0)+(u_2-u_1)+\\cdots+(u_n-u_{n-1})={{eval:r}}+{{eval:r}}+\\cdots+{{eval:r}}$$\n\nLes termes $u_1$, …, $u_{n-1}$ se simplifient. Complète.\n\n$u_n-u_0=?$","variables":[{"name":"a","expression":"1..9"},{"name":"r","expression":"2..9"}],"blanks":[{"expectedAnswer":"{{eval:r}}n"}],"correction":{"steps":["Dans le membre de gauche, chacun des termes $u_1$, …, $u_{n-1}$ apparaît une fois avec le signe $+$ et une fois avec le signe $-$ : il ne reste que $u_n-u_0$.","Le membre de droite compte $n$ termes (un par valeur de $k$, de $0$ à $n-1$), tous égaux à ${{eval:r}}$.","Donc $u_n-u_0=\\textcolor{{{color:primary.0}}}{{{eval:r}}n}$, soit $u_n={{eval:a}}+{{eval:r}}n$."]}},{"statement":"Soit $(u_n)$ la suite arithmétique de premier terme $u_0={{eval:a}}$ et de raison ${{eval:r}}$. On cherche l'expression de $u_n$ en fonction de $n$, pour tout entier naturel $n$ non nul.\n\nPour tout entier naturel $k$, $u_{k+1}-u_k={{eval:r}}$. On écrit cette égalité pour $k=0$, $k=1$, …, $k=n-1$, puis on additionne membre à membre :\n\n$$(u_1-u_0)+(u_2-u_1)+\\cdots+(u_n-u_{n-1})={{eval:r}}+{{eval:r}}+\\cdots+{{eval:r}}$$\n\nCombien de termes la somme ${{eval:r}}+{{eval:r}}+\\cdots+{{eval:r}}$ du membre de droite compte-t-elle ?\n\n$?$","variables":[{"name":"a","expression":"1..9"},{"name":"r","expression":"2..9"}],"blanks":[{"expectedAnswer":"n"}],"correction":{"steps":["On a écrit une égalité pour chaque valeur de $k$ de $0$ à $n-1$ : il y en a $n$.","Le membre de droite compte donc $\\textcolor{{{color:primary.0}}}{n}$ termes égaux à ${{eval:r}}$ : $u_n-u_0={{eval:r}}n$.","Attention : de $0$ à $n-1$, il y a $n$ entiers, pas $n-1$ ni $n+1$."]}},{"statement":"Soit $(u_n)$ la suite arithmétique de premier terme $u_0={{eval:a}}$ et de raison ${{eval:r}}$. On cherche l'expression de $u_n$ en fonction de $n$, pour tout entier naturel $n$ non nul.\n\nPour tout entier naturel $k$, $u_{k+1}-u_k={{eval:r}}$. On écrit cette égalité pour $k=0$, $k=1$, …, $k=n-1$, puis on additionne membre à membre :\n\n$$(u_1-u_0)+(u_2-u_1)+\\cdots+(u_n-u_{n-1})={{eval:r}}+{{eval:r}}+\\cdots+{{eval:r}}$$\n\nLe membre de gauche est égal à $u_n-u_0$. Pourquoi ?\n\n```choix\n- Chacun des termes $u_1$, …, $u_{n-1}$ apparaît une fois avec le signe $+$ et une fois avec le signe $-$.\n- Les termes $u_1$, …, $u_{n-1}$ sont tous égaux à $0$.\n- Les termes $u_1$, …, $u_{n-1}$ sont tous égaux à ${{eval:r}}$.\n- La suite $(u_n)$ est constante.\n```","variables":[{"name":"a","expression":"1..9"},{"name":"r","expression":"2..9"}],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["$\\textcolor{{{color:primary.0}}}{u_1}$ apparaît dans $(u_1-u_0)$ avec le signe $+$ et dans $(u_2-u_1)$ avec le signe $-$ ; de même pour $u_2$, …, $u_{n-1}$.","Ces termes se compensent deux à deux : il ne reste que $u_n-u_0$.","Les termes de la suite ne sont ni nuls ni égaux à la raison : la suite augmente de ${{eval:r}}$ à chaque rang."]}}],"shared":{},"test_specs":[{"description":"3n","variationIndex":0,"variables":{"a":"4","r":"3"},"answers":["3n"],"expected":{"status":"correct"}},{"description":"Erreur : 3(n + 1)","variationIndex":0,"variables":{"a":"4","r":"3"},"answers":["3(n+1)"],"expected":{"status":"incorrect"}},{"description":"Erreur : 4 + 3n (uₙ au lieu de uₙ − u₀)","variationIndex":0,"variables":{"a":"4","r":"3"},"answers":["4+3n"],"expected":{"status":"incorrect"}},{"description":"Erreur : 3(n − 1)","variationIndex":0,"variables":{"a":"4","r":"3"},"answers":["3(n-1)"],"expected":{"status":"incorrect"}},{"description":"n","variationIndex":1,"variables":{"a":"4","r":"3"},"answers":["n"],"expected":{"status":"correct"}},{"description":"Erreur : n − 1","variationIndex":1,"variables":{"a":"4","r":"3"},"answers":["n-1"],"expected":{"status":"incorrect"}},{"description":"Erreur : n + 1","variationIndex":1,"variables":{"a":"4","r":"3"},"answers":["n+1"],"expected":{"status":"incorrect"}},{"description":"télescopage","variationIndex":2,"variables":{"a":"4","r":"3"},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : termes nuls","variationIndex":2,"variables":{"a":"4","r":"3"},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : termes égaux à r","variationIndex":2,"variables":{"a":"4","r":"3"},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : suite constante","variationIndex":2,"variables":{"a":"4","r":"3"},"answers":["3"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
  $qdeme${"title":"Démontrer le terme général d'une suite arithmétique","description":"Démonstration à trous de uₙ = u₀ + nr (somme télescopique des n égalités uₖ₊₁ − uₖ = r) : uₙ − u₀ à compléter, nombre de termes de la somme, justification du télescopage","variations":[{"statement":"Soit $(u_n)$ la suite arithmétique de premier terme $u_0={{eval:a}}$ et de raison ${{eval:r}}$. On cherche l'expression de $u_n$ en fonction de $n$, pour tout entier naturel $n$ non nul.\n\nPour tout entier naturel $k$, $u_{k+1}-u_k={{eval:r}}$. On écrit cette égalité pour $k=0$, $k=1$, …, $k=n-1$, puis on additionne membre à membre :\n\n$$(u_1-u_0)+(u_2-u_1)+\\cdots+(u_n-u_{n-1})={{eval:r}}+{{eval:r}}+\\cdots+{{eval:r}}$$\n\nLes termes $u_1$, …, $u_{n-1}$ se simplifient. Complète.\n\n$u_n-u_0=?$","variables":[{"name":"a","expression":"1..9"},{"name":"r","expression":"2..9"}],"blanks":[{"expectedAnswer":"{{eval:r}}n"}],"correction":{"steps":["Dans le membre de gauche, chacun des termes $u_1$, …, $u_{n-1}$ apparaît une fois avec le signe $+$ et une fois avec le signe $-$ : il ne reste que $u_n-u_0$.","Le membre de droite compte $n$ termes (un par valeur de $k$, de $0$ à $n-1$), tous égaux à ${{eval:r}}$.","Donc $u_n-u_0=\\textcolor{{{color:primary.0}}}{{{eval:r}}n}$, soit $u_n={{eval:a}}+{{eval:r}}n$."]}},{"statement":"Soit $(u_n)$ la suite arithmétique de premier terme $u_0={{eval:a}}$ et de raison ${{eval:r}}$. On cherche l'expression de $u_n$ en fonction de $n$, pour tout entier naturel $n$ non nul.\n\nPour tout entier naturel $k$, $u_{k+1}-u_k={{eval:r}}$. On écrit cette égalité pour $k=0$, $k=1$, …, $k=n-1$, puis on additionne membre à membre :\n\n$$(u_1-u_0)+(u_2-u_1)+\\cdots+(u_n-u_{n-1})={{eval:r}}+{{eval:r}}+\\cdots+{{eval:r}}$$\n\nCombien de termes la somme ${{eval:r}}+{{eval:r}}+\\cdots+{{eval:r}}$ du membre de droite compte-t-elle ?\n\n$?$","variables":[{"name":"a","expression":"1..9"},{"name":"r","expression":"2..9"}],"blanks":[{"expectedAnswer":"n"}],"correction":{"steps":["On a écrit une égalité pour chaque valeur de $k$ de $0$ à $n-1$ : il y en a $n$.","Le membre de droite compte donc $\\textcolor{{{color:primary.0}}}{n}$ termes égaux à ${{eval:r}}$ : $u_n-u_0={{eval:r}}n$.","Attention : de $0$ à $n-1$, il y a $n$ entiers, pas $n-1$ ni $n+1$."]}},{"statement":"Soit $(u_n)$ la suite arithmétique de premier terme $u_0={{eval:a}}$ et de raison ${{eval:r}}$. On cherche l'expression de $u_n$ en fonction de $n$, pour tout entier naturel $n$ non nul.\n\nPour tout entier naturel $k$, $u_{k+1}-u_k={{eval:r}}$. On écrit cette égalité pour $k=0$, $k=1$, …, $k=n-1$, puis on additionne membre à membre :\n\n$$(u_1-u_0)+(u_2-u_1)+\\cdots+(u_n-u_{n-1})={{eval:r}}+{{eval:r}}+\\cdots+{{eval:r}}$$\n\nLe membre de gauche est égal à $u_n-u_0$. Pourquoi ?\n\n```choix\n- Chacun des termes $u_1$, …, $u_{n-1}$ apparaît une fois avec le signe $+$ et une fois avec le signe $-$.\n- Les termes $u_1$, …, $u_{n-1}$ sont tous égaux à $0$.\n- Les termes $u_1$, …, $u_{n-1}$ sont tous égaux à ${{eval:r}}$.\n- La suite $(u_n)$ est constante.\n```","variables":[{"name":"a","expression":"1..9"},{"name":"r","expression":"2..9"}],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["$\\textcolor{{{color:primary.0}}}{u_1}$ apparaît dans $(u_1-u_0)$ avec le signe $+$ et dans $(u_2-u_1)$ avec le signe $-$ ; de même pour $u_2$, …, $u_{n-1}$.","Ces termes se compensent deux à deux : il ne reste que $u_n-u_0$.","Les termes de la suite ne sont ni nuls ni égaux à la raison : la suite augmente de ${{eval:r}}$ à chaque rang."]}},{"statement":"Soit $(u_n)$ une suite arithmétique de raison $r$, et $n$ un entier naturel non nul. On démontre que $u_n=u_0+nr$.\n\nRemets les étapes de la démonstration dans l'ordre.\n\n```ranger\nsigne: aucun\n- Pour tout entier naturel $k$, $u_{k+1}-u_k=r$.\n- On écrit cette égalité pour $k=0$, …, $k=n-1$ et on additionne : $(u_1-u_0)+\\cdots+(u_n-u_{n-1})=r+\\cdots+r$.\n- Les termes $u_1$, …, $u_{n-1}$ se simplifient, et le membre de droite compte $n$ termes : $u_n-u_0=nr$.\n- Donc $u_n=u_0+nr$.\n```","variables":[],"correction":{"steps":["On part de la définition (la différence de deux termes consécutifs vaut $r$), on l'écrit $n$ fois, puis on additionne.","La somme se télescope : il reste $u_n-u_0=nr$, d'où $\\textcolor{{{color:primary.0}}}{u_n=u_0+nr}$."]}}],"shared":{},"test_specs":[{"description":"3n","variationIndex":0,"variables":{"a":"4","r":"3"},"answers":["3n"],"expected":{"status":"correct"}},{"description":"Erreur : 3(n + 1)","variationIndex":0,"variables":{"a":"4","r":"3"},"answers":["3(n+1)"],"expected":{"status":"incorrect"}},{"description":"Erreur : 4 + 3n (uₙ au lieu de uₙ − u₀)","variationIndex":0,"variables":{"a":"4","r":"3"},"answers":["4+3n"],"expected":{"status":"incorrect"}},{"description":"Erreur : 3(n − 1)","variationIndex":0,"variables":{"a":"4","r":"3"},"answers":["3(n-1)"],"expected":{"status":"incorrect"}},{"description":"n","variationIndex":1,"variables":{"a":"4","r":"3"},"answers":["n"],"expected":{"status":"correct"}},{"description":"Erreur : n − 1","variationIndex":1,"variables":{"a":"4","r":"3"},"answers":["n-1"],"expected":{"status":"incorrect"}},{"description":"Erreur : n + 1","variationIndex":1,"variables":{"a":"4","r":"3"},"answers":["n+1"],"expected":{"status":"incorrect"}},{"description":"télescopage","variationIndex":2,"variables":{"a":"4","r":"3"},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : termes nuls","variationIndex":2,"variables":{"a":"4","r":"3"},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : termes égaux à r","variationIndex":2,"variables":{"a":"4","r":"3"},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : suite constante","variationIndex":2,"variables":{"a":"4","r":"3"},"answers":["3"],"expected":{"status":"incorrect"}},{"description":"Étapes dans l’ordre","variationIndex":3,"variables":{},"answers":["3","0","1","2"],"expected":{"status":"correct"}},{"description":"Erreur : deuxième et troisième étapes échangées","variationIndex":3,"variables":{},"answers":["3","1","0","2"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
  null, null, null);
insert into _qdeme_modeles values ('acaeb02a-e934-43b6-99bc-46bb1ffb4f0f', $qdeme$Suites$qdeme$, $qdeme$Suites géométriques$qdeme$, $qdeme$terme général$qdeme$, array['1_SPE'], 'published',
  $qdeme${"title":"Démontrer le terme général d'une suite géométrique","description":"Démonstration à trous de uₙ = u₀qⁿ : produit télescopique des n quotients uₖ₊₁/uₖ = q, calcul de proche en proche jusqu'à u₃, justification de l'existence des quotients","variations":[{"statement":"Soit $(u_n)$ la suite géométrique de premier terme $u_0={{eval:a}}$ et de raison ${{eval:q}}$. On cherche l'expression de $u_n$ en fonction de $n$, pour tout entier naturel $n$ non nul.\n\nPour tout entier naturel $k$, $u_{k+1}={{eval:q}}\\times u_k$. Comme $u_0\\neq 0$ et ${{eval:q}}\\neq 0$, aucun terme de la suite n'est nul, et pour tout $k$, $\\dfrac{u_{k+1}}{u_k}={{eval:q}}$. On écrit cette égalité pour $k=0$, …, $k=n-1$, puis on multiplie membre à membre :\n\n$$\\dfrac{u_1}{u_0}\\times\\dfrac{u_2}{u_1}\\times\\cdots\\times\\dfrac{u_n}{u_{n-1}}={{eval:q}}\\times{{eval:q}}\\times\\cdots\\times{{eval:q}}$$\n\nLes termes $u_1$, …, $u_{n-1}$ se simplifient. Complète.\n\n$\\dfrac{u_n}{u_0}=?$","variables":[{"name":"a","expression":"1..9"},{"name":"q","expression":"2..5"}],"blanks":[{"expectedAnswer":"{{eval:q}}^n"}],"correction":{"steps":["Dans le membre de gauche, chaque terme $u_1$, …, $u_{n-1}$ est une fois au numérateur et une fois au dénominateur : il reste $\\dfrac{u_n}{u_0}$.","Le membre de droite est le produit de $n$ facteurs égaux à ${{eval:q}}$.","Donc $\\dfrac{u_n}{u_0}=\\textcolor{{{color:primary.0}}}{{{eval:q}}^n}$, soit $u_n={{eval:a}}\\times{{eval:q}}^n$."]}},{"statement":"Soit $(u_n)$ la suite géométrique de premier terme $u_0={{eval:a}}$ et de raison ${{eval:q}}$. On cherche l'expression de $u_n$ en fonction de $n$, pour tout entier naturel $n$ non nul.\n\nPour tout entier naturel $k$, $u_{k+1}={{eval:q}}\\times u_k$. On calcule les premiers termes de proche en proche :\n\n$$u_1={{eval:q}}\\times u_0,\\qquad u_2={{eval:q}}\\times u_1={{eval:q}}^2\\times u_0$$\n\nComplète.\n\n$u_3={{eval:q}}\\times u_2=?\\times u_0$","variables":[{"name":"a","expression":"1..9"},{"name":"q","expression":"2..5"}],"blanks":[{"expectedAnswer":"{{eval:q^3}}","requiredForm":{"pattern":"u"}}],"correction":{"steps":["$u_3={{eval:q}}\\times u_2={{eval:q}}\\times{{eval:q}}^2\\times u_0={{eval:q}}^3\\times u_0$.","Donc $u_3=\\textcolor{{{color:primary.0}}}{{{eval:q^3}}}\\times u_0$ : à chaque rang, on multiplie une fois de plus par la raison.","De même, $u_n={{eval:q}}^n\\times u_0$ : il y a $n$ multiplications par ${{eval:q}}$ de $u_0$ à $u_n$."]}},{"statement":"Soit $(u_n)$ la suite géométrique de premier terme $u_0={{eval:a}}$ et de raison ${{eval:q}}$. On cherche l'expression de $u_n$ en fonction de $n$, pour tout entier naturel $n$ non nul.\n\nPour tout entier naturel $k$, $u_{k+1}={{eval:q}}\\times u_k$. Pour démontrer l'expression de $u_n$, on veut écrire les quotients $\\dfrac{u_{k+1}}{u_k}$. Pourquoi ces quotients existent-ils ?\n\n```choix\n- Car $u_0\\neq 0$ et la raison est non nulle : aucun terme de la suite n'est nul.\n- Car la suite $(u_n)$ est arithmétique.\n- Car on peut toujours diviser par un terme d'une suite.\n- Car $u_{k+1}-u_k$ est constant.\n```","variables":[{"name":"a","expression":"1..9"},{"name":"q","expression":"2..5"}],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["Un quotient $\\dfrac{u_{k+1}}{u_k}$ n'existe que si $u_k\\neq 0$.","Ici $u_0={{eval:a}}\\neq 0$ et $u_{k+1}={{eval:q}}\\times u_k$ avec ${{eval:q}}\\neq 0$ : de proche en proche, **aucun terme n'est nul**.","La suite est géométrique, pas arithmétique : c'est le quotient de deux termes consécutifs qui est constant, pas leur différence."]}}],"shared":{},"test_specs":[{"description":"2ⁿ","variationIndex":0,"variables":{"a":"5","q":"2"},"answers":["2^n"],"expected":{"status":"correct"}},{"description":"Erreur : 2n (raisonnement arithmétique)","variationIndex":0,"variables":{"a":"5","q":"2"},"answers":["2n"],"expected":{"status":"incorrect"}},{"description":"Erreur : 2ⁿ⁺¹","variationIndex":0,"variables":{"a":"5","q":"2"},"answers":["2^{n+1}"],"expected":{"status":"incorrect"}},{"description":"Erreur : 5 × 2ⁿ (uₙ au lieu du quotient)","variationIndex":0,"variables":{"a":"5","q":"2"},"answers":["5\\times2^n"],"expected":{"status":"incorrect"}},{"description":"8","variationIndex":1,"variables":{"a":"5","q":"2"},"answers":["8"],"expected":{"status":"correct"}},{"description":"Écriture 2³","variationIndex":1,"variables":{"a":"5","q":"2"},"answers":["2^3"],"expected":{"status":"correct"}},{"description":"Erreur : 6 (3 × 2)","variationIndex":1,"variables":{"a":"5","q":"2"},"answers":["6"],"expected":{"status":"incorrect"}},{"description":"Erreur : 4 (2²)","variationIndex":1,"variables":{"a":"5","q":"2"},"answers":["4"],"expected":{"status":"incorrect"}},{"description":"aucun terme nul","variationIndex":2,"variables":{"a":"5","q":"2"},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : arithmétique","variationIndex":2,"variables":{"a":"5","q":"2"},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : toujours possible","variationIndex":2,"variables":{"a":"5","q":"2"},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : différence","variationIndex":2,"variables":{"a":"5","q":"2"},"answers":["3"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
  $qdeme${"title":"Démontrer le terme général d'une suite géométrique","description":"Démonstration à trous de uₙ = u₀qⁿ : produit télescopique des n quotients uₖ₊₁/uₖ = q, calcul de proche en proche jusqu'à u₃, justification de l'existence des quotients","variations":[{"statement":"Soit $(u_n)$ la suite géométrique de premier terme $u_0={{eval:a}}$ et de raison ${{eval:q}}$. On cherche l'expression de $u_n$ en fonction de $n$, pour tout entier naturel $n$ non nul.\n\nPour tout entier naturel $k$, $u_{k+1}={{eval:q}}\\times u_k$. Comme $u_0\\neq 0$ et ${{eval:q}}\\neq 0$, aucun terme de la suite n'est nul, et pour tout $k$, $\\dfrac{u_{k+1}}{u_k}={{eval:q}}$. On écrit cette égalité pour $k=0$, …, $k=n-1$, puis on multiplie membre à membre :\n\n$$\\dfrac{u_1}{u_0}\\times\\dfrac{u_2}{u_1}\\times\\cdots\\times\\dfrac{u_n}{u_{n-1}}={{eval:q}}\\times{{eval:q}}\\times\\cdots\\times{{eval:q}}$$\n\nLes termes $u_1$, …, $u_{n-1}$ se simplifient. Complète.\n\n$\\dfrac{u_n}{u_0}=?$","variables":[{"name":"a","expression":"1..9"},{"name":"q","expression":"2..5"}],"blanks":[{"expectedAnswer":"{{eval:q}}^n"}],"correction":{"steps":["Dans le membre de gauche, chaque terme $u_1$, …, $u_{n-1}$ est une fois au numérateur et une fois au dénominateur : il reste $\\dfrac{u_n}{u_0}$.","Le membre de droite est le produit de $n$ facteurs égaux à ${{eval:q}}$.","Donc $\\dfrac{u_n}{u_0}=\\textcolor{{{color:primary.0}}}{{{eval:q}}^n}$, soit $u_n={{eval:a}}\\times{{eval:q}}^n$."]}},{"statement":"Soit $(u_n)$ la suite géométrique de premier terme $u_0={{eval:a}}$ et de raison ${{eval:q}}$. On cherche l'expression de $u_n$ en fonction de $n$, pour tout entier naturel $n$ non nul.\n\nPour tout entier naturel $k$, $u_{k+1}={{eval:q}}\\times u_k$. On calcule les premiers termes de proche en proche :\n\n$$u_1={{eval:q}}\\times u_0,\\qquad u_2={{eval:q}}\\times u_1={{eval:q}}^2\\times u_0$$\n\nComplète.\n\n$u_3={{eval:q}}\\times u_2=?\\times u_0$","variables":[{"name":"a","expression":"1..9"},{"name":"q","expression":"2..5"}],"blanks":[{"expectedAnswer":"{{eval:q^3}}","requiredForm":{"pattern":"u"}}],"correction":{"steps":["$u_3={{eval:q}}\\times u_2={{eval:q}}\\times{{eval:q}}^2\\times u_0={{eval:q}}^3\\times u_0$.","Donc $u_3=\\textcolor{{{color:primary.0}}}{{{eval:q^3}}}\\times u_0$ : à chaque rang, on multiplie une fois de plus par la raison.","De même, $u_n={{eval:q}}^n\\times u_0$ : il y a $n$ multiplications par ${{eval:q}}$ de $u_0$ à $u_n$."]}},{"statement":"Soit $(u_n)$ la suite géométrique de premier terme $u_0={{eval:a}}$ et de raison ${{eval:q}}$. On cherche l'expression de $u_n$ en fonction de $n$, pour tout entier naturel $n$ non nul.\n\nPour tout entier naturel $k$, $u_{k+1}={{eval:q}}\\times u_k$. Pour démontrer l'expression de $u_n$, on veut écrire les quotients $\\dfrac{u_{k+1}}{u_k}$. Pourquoi ces quotients existent-ils ?\n\n```choix\n- Car $u_0\\neq 0$ et la raison est non nulle : aucun terme de la suite n'est nul.\n- Car la suite $(u_n)$ est arithmétique.\n- Car on peut toujours diviser par un terme d'une suite.\n- Car $u_{k+1}-u_k$ est constant.\n```","variables":[{"name":"a","expression":"1..9"},{"name":"q","expression":"2..5"}],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["Un quotient $\\dfrac{u_{k+1}}{u_k}$ n'existe que si $u_k\\neq 0$.","Ici $u_0={{eval:a}}\\neq 0$ et $u_{k+1}={{eval:q}}\\times u_k$ avec ${{eval:q}}\\neq 0$ : de proche en proche, **aucun terme n'est nul**.","La suite est géométrique, pas arithmétique : c'est le quotient de deux termes consécutifs qui est constant, pas leur différence."]}},{"statement":"Soit $(u_n)$ une suite géométrique de premier terme $u_0\\neq 0$ et de raison $q\\neq 0$, et $n$ un entier naturel non nul. On démontre que $u_n=u_0q^n$.\n\nRemets les étapes de la démonstration dans l'ordre.\n\n```ranger\nsigne: aucun\n- Pour tout entier naturel $k$, $u_{k+1}=q\\times u_k$ : de proche en proche, aucun terme n'est nul.\n- Donc pour tout entier naturel $k$, $\\dfrac{u_{k+1}}{u_k}=q$.\n- On écrit cette égalité pour $k=0$, …, $k=n-1$ et on multiplie : $\\dfrac{u_1}{u_0}\\times\\cdots\\times\\dfrac{u_n}{u_{n-1}}=q\\times\\cdots\\times q$.\n- Les termes $u_1$, …, $u_{n-1}$ se simplifient : $\\dfrac{u_n}{u_0}=q^n$.\n- Donc $u_n=u_0q^n$.\n```","variables":[],"correction":{"steps":["Avant d'écrire un quotient $\\dfrac{u_{k+1}}{u_k}$, il faut savoir que $u_k\\neq 0$ : c'est la première étape.","Le produit des $n$ quotients se télescope : $\\dfrac{u_n}{u_0}=q^n$, d'où $\\textcolor{{{color:primary.0}}}{u_n=u_0q^n}$."]}}],"shared":{},"test_specs":[{"description":"2ⁿ","variationIndex":0,"variables":{"a":"5","q":"2"},"answers":["2^n"],"expected":{"status":"correct"}},{"description":"Erreur : 2n (raisonnement arithmétique)","variationIndex":0,"variables":{"a":"5","q":"2"},"answers":["2n"],"expected":{"status":"incorrect"}},{"description":"Erreur : 2ⁿ⁺¹","variationIndex":0,"variables":{"a":"5","q":"2"},"answers":["2^{n+1}"],"expected":{"status":"incorrect"}},{"description":"Erreur : 5 × 2ⁿ (uₙ au lieu du quotient)","variationIndex":0,"variables":{"a":"5","q":"2"},"answers":["5\\times2^n"],"expected":{"status":"incorrect"}},{"description":"8","variationIndex":1,"variables":{"a":"5","q":"2"},"answers":["8"],"expected":{"status":"correct"}},{"description":"Écriture 2³","variationIndex":1,"variables":{"a":"5","q":"2"},"answers":["2^3"],"expected":{"status":"correct"}},{"description":"Erreur : 6 (3 × 2)","variationIndex":1,"variables":{"a":"5","q":"2"},"answers":["6"],"expected":{"status":"incorrect"}},{"description":"Erreur : 4 (2²)","variationIndex":1,"variables":{"a":"5","q":"2"},"answers":["4"],"expected":{"status":"incorrect"}},{"description":"aucun terme nul","variationIndex":2,"variables":{"a":"5","q":"2"},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : arithmétique","variationIndex":2,"variables":{"a":"5","q":"2"},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : toujours possible","variationIndex":2,"variables":{"a":"5","q":"2"},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : différence","variationIndex":2,"variables":{"a":"5","q":"2"},"answers":["3"],"expected":{"status":"incorrect"}},{"description":"Étapes dans l’ordre","variationIndex":3,"variables":{},"answers":["4","0","1","2","3"],"expected":{"status":"correct"}},{"description":"Erreur : deuxième et troisième étapes échangées","variationIndex":3,"variables":{},"answers":["4","1","0","2","3"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
  null, null, null);
insert into _qdeme_modeles values ('b05ec37a-3e3a-4a98-bd32-635636b84281', $qdeme$Fonctions$qdeme$, $qdeme$Dérivation$qdeme$, $qdeme$fonctions dérivées$qdeme$, array['1_SPE'], 'published',
  $qdeme${"title":"Démontrer la dérivée de la fonction carré","description":"Démonstration à trous de (x²)′ = 2x par le taux de variation entre a et a + h : (a + h)² − a² à développer, taux 2a + h, justification de la limite","variations":[{"statement":"Soit $f$ la fonction carré, définie sur $\\mathbb{R}$ par $f(x)=x^2$, et $a$ un réel. Pour $h\\neq 0$, on calcule le taux de variation de $f$ entre $a$ et $a+h$ :\n\n$$\\dfrac{f(a+h)-f(a)}{h}=\\dfrac{(a+h)^2-a^2}{h}$$\n\nOn développe $(a+h)^2$, puis on réduit. Complète par une expression développée.\n\n$(a+h)^2-a^2=?$","variables":[],"blanks":[{"expectedAnswer":"2ah+h^2","requiredForm":{"pattern":"u"}}],"correction":{"steps":["$(a+h)^2=a^2+2ah+h^2$ (identité remarquable).","Donc $(a+h)^2-a^2=\\textcolor{{{color:primary.0}}}{2ah+h^2}$ : les $a^2$ se compensent."]}},{"statement":"Soit $f$ la fonction carré, définie sur $\\mathbb{R}$ par $f(x)=x^2$, et $a$ un réel. Pour $h\\neq 0$, on calcule le taux de variation de $f$ entre $a$ et $a+h$ :\n\n$$\\dfrac{f(a+h)-f(a)}{h}=\\dfrac{(a+h)^2-a^2}{h}$$\n\nComme $(a+h)^2-a^2=2ah+h^2$, on simplifie par $h$. Complète.\n\n$\\dfrac{f(a+h)-f(a)}{h}=\\dfrac{2ah+h^2}{h}=?$","variables":[],"blanks":[{"expectedAnswer":"2a+h","requiredForm":{"pattern":"u"}}],"correction":{"steps":["$2ah+h^2=h(2a+h)$ : on met $h$ en facteur.","Comme $h\\neq 0$, on simplifie : le taux vaut $\\textcolor{{{color:primary.0}}}{2a+h}$."]}},{"statement":"Soit $f$ la fonction carré, définie sur $\\mathbb{R}$ par $f(x)=x^2$, et $a$ un réel. Pour $h\\neq 0$, on calcule le taux de variation de $f$ entre $a$ et $a+h$ :\n\n$$\\dfrac{f(a+h)-f(a)}{h}=\\dfrac{(a+h)^2-a^2}{h}$$\n\nCe taux vaut $2a+h$. On en déduit que $f$ est dérivable en $a$, avec $f'(a)=2a$. Pourquoi ?\n\n```choix\n- Car quand $h$ tend vers $0$, $2a+h$ tend vers $2a$.\n- Car $2a+h=2a$ pour tout réel $h$.\n- Car on remplace $h$ par $0$ dans $\\dfrac{(a+h)^2-a^2}{h}$.\n- Car $f(a)=a^2$, et on multiplie par $2$.\n```","variables":[],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["Le nombre dérivé est la limite du taux quand $h$ tend vers $0$.","Ici le taux vaut $2a+h$, qui tend vers $\\textcolor{{{color:primary.0}}}{2a}$ : $f'(a)=2a$.","On ne peut pas remplacer $h$ par $0$ dans $\\dfrac{(a+h)^2-a^2}{h}$ : on diviserait par $0$. C'est pour cela qu'on simplifie d'abord."]}}],"shared":{},"test_specs":[{"description":"2ah + h²","variationIndex":0,"variables":{},"answers":["2ah+h^2"],"expected":{"status":"correct"}},{"description":"Écriture h² + 2ah","variationIndex":0,"variables":{},"answers":["h^2+2ah"],"expected":{"status":"correct"}},{"description":"Erreur : h²","variationIndex":0,"variables":{},"answers":["h^2"],"expected":{"status":"incorrect"}},{"description":"Erreur : 2ah","variationIndex":0,"variables":{},"answers":["2ah"],"expected":{"status":"incorrect"}},{"description":"Erreur : 2a + h (taux au lieu de la différence)","variationIndex":0,"variables":{},"answers":["2a+h"],"expected":{"status":"incorrect"}},{"description":"2a + h","variationIndex":1,"variables":{},"answers":["2a+h"],"expected":{"status":"correct"}},{"description":"Erreur : 2a (limite au lieu du taux)","variationIndex":1,"variables":{},"answers":["2a"],"expected":{"status":"incorrect"}},{"description":"Erreur : 2ah + h","variationIndex":1,"variables":{},"answers":["2ah+h"],"expected":{"status":"incorrect"}},{"description":"Erreur : a + h","variationIndex":1,"variables":{},"answers":["a+h"],"expected":{"status":"incorrect"}},{"description":"limite de 2a + h","variationIndex":2,"variables":{},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : égalité pour tout h","variationIndex":2,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : h remplacé par 0","variationIndex":2,"variables":{},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : f(a) multiplié par 2","variationIndex":2,"variables":{},"answers":["3"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
  $qdeme${"title":"Démontrer la dérivée de la fonction carré","description":"Démonstration à trous de (x²)′ = 2x par le taux de variation entre a et a + h : (a + h)² − a² à développer, taux 2a + h, justification de la limite","variations":[{"statement":"Soit $f$ la fonction carré, définie sur $\\mathbb{R}$ par $f(x)=x^2$, et $a$ un réel. Pour $h\\neq 0$, on calcule le taux de variation de $f$ entre $a$ et $a+h$ :\n\n$$\\dfrac{f(a+h)-f(a)}{h}=\\dfrac{(a+h)^2-a^2}{h}$$\n\nOn développe $(a+h)^2$, puis on réduit. Complète par une expression développée.\n\n$(a+h)^2-a^2=?$","variables":[],"blanks":[{"expectedAnswer":"2ah+h^2","requiredForm":{"pattern":"u"}}],"correction":{"steps":["$(a+h)^2=a^2+2ah+h^2$ (identité remarquable).","Donc $(a+h)^2-a^2=\\textcolor{{{color:primary.0}}}{2ah+h^2}$ : les $a^2$ se compensent."]}},{"statement":"Soit $f$ la fonction carré, définie sur $\\mathbb{R}$ par $f(x)=x^2$, et $a$ un réel. Pour $h\\neq 0$, on calcule le taux de variation de $f$ entre $a$ et $a+h$ :\n\n$$\\dfrac{f(a+h)-f(a)}{h}=\\dfrac{(a+h)^2-a^2}{h}$$\n\nComme $(a+h)^2-a^2=2ah+h^2$, on simplifie par $h$. Complète.\n\n$\\dfrac{f(a+h)-f(a)}{h}=\\dfrac{2ah+h^2}{h}=?$","variables":[],"blanks":[{"expectedAnswer":"2a+h","requiredForm":{"pattern":"u"}}],"correction":{"steps":["$2ah+h^2=h(2a+h)$ : on met $h$ en facteur.","Comme $h\\neq 0$, on simplifie : le taux vaut $\\textcolor{{{color:primary.0}}}{2a+h}$."]}},{"statement":"Soit $f$ la fonction carré, définie sur $\\mathbb{R}$ par $f(x)=x^2$, et $a$ un réel. Pour $h\\neq 0$, on calcule le taux de variation de $f$ entre $a$ et $a+h$ :\n\n$$\\dfrac{f(a+h)-f(a)}{h}=\\dfrac{(a+h)^2-a^2}{h}$$\n\nCe taux vaut $2a+h$. On en déduit que $f$ est dérivable en $a$, avec $f'(a)=2a$. Pourquoi ?\n\n```choix\n- Car quand $h$ tend vers $0$, $2a+h$ tend vers $2a$.\n- Car $2a+h=2a$ pour tout réel $h$.\n- Car on remplace $h$ par $0$ dans $\\dfrac{(a+h)^2-a^2}{h}$.\n- Car $f(a)=a^2$, et on multiplie par $2$.\n```","variables":[],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["Le nombre dérivé est la limite du taux quand $h$ tend vers $0$.","Ici le taux vaut $2a+h$, qui tend vers $\\textcolor{{{color:primary.0}}}{2a}$ : $f'(a)=2a$.","On ne peut pas remplacer $h$ par $0$ dans $\\dfrac{(a+h)^2-a^2}{h}$ : on diviserait par $0$. C'est pour cela qu'on simplifie d'abord."]}},{"statement":"Soit $f$ la fonction carré, définie sur $\\mathbb{R}$ par $f(x)=x^2$, $a$ un réel et $h$ un réel non nul. On démontre que $f'(a)=2a$.\n\nRemets les étapes de la démonstration dans l'ordre.\n\n```ranger\nsigne: aucun\n- $f(a+h)-f(a)=(a+h)^2-a^2=2ah+h^2$.\n- Le taux de variation vaut $\\dfrac{f(a+h)-f(a)}{h}=\\dfrac{2ah+h^2}{h}=2a+h$.\n- Quand $h$ tend vers $0$, le taux $2a+h$ tend vers $2a$.\n- Donc $f$ est dérivable en $a$ et $f'(a)=2a$.\n```","variables":[],"correction":{"steps":["On développe, on simplifie le taux par $h$ (non nul), puis on fait tendre $h$ vers $0$.","Le taux tend vers $2a$ : $\\textcolor{{{color:primary.0}}}{f'(a)=2a}$."]}}],"shared":{},"test_specs":[{"description":"2ah + h²","variationIndex":0,"variables":{},"answers":["2ah+h^2"],"expected":{"status":"correct"}},{"description":"Écriture h² + 2ah","variationIndex":0,"variables":{},"answers":["h^2+2ah"],"expected":{"status":"correct"}},{"description":"Erreur : h²","variationIndex":0,"variables":{},"answers":["h^2"],"expected":{"status":"incorrect"}},{"description":"Erreur : 2ah","variationIndex":0,"variables":{},"answers":["2ah"],"expected":{"status":"incorrect"}},{"description":"Erreur : 2a + h (taux au lieu de la différence)","variationIndex":0,"variables":{},"answers":["2a+h"],"expected":{"status":"incorrect"}},{"description":"2a + h","variationIndex":1,"variables":{},"answers":["2a+h"],"expected":{"status":"correct"}},{"description":"Erreur : 2a (limite au lieu du taux)","variationIndex":1,"variables":{},"answers":["2a"],"expected":{"status":"incorrect"}},{"description":"Erreur : 2ah + h","variationIndex":1,"variables":{},"answers":["2ah+h"],"expected":{"status":"incorrect"}},{"description":"Erreur : a + h","variationIndex":1,"variables":{},"answers":["a+h"],"expected":{"status":"incorrect"}},{"description":"limite de 2a + h","variationIndex":2,"variables":{},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : égalité pour tout h","variationIndex":2,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : h remplacé par 0","variationIndex":2,"variables":{},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : f(a) multiplié par 2","variationIndex":2,"variables":{},"answers":["3"],"expected":{"status":"incorrect"}},{"description":"Étapes dans l’ordre","variationIndex":3,"variables":{},"answers":["3","0","1","2"],"expected":{"status":"correct"}},{"description":"Erreur : deuxième et troisième étapes échangées","variationIndex":3,"variables":{},"answers":["3","1","0","2"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
  null, null, null);
insert into _qdeme_modeles values ('b554a47f-1b2e-4530-a979-44d785890adf', $qdeme$Suites$qdeme$, $qdeme$Suites géométriques$qdeme$, $qdeme$somme des termes$qdeme$, array['1_SPE'], 'published',
  $qdeme${"title":"Démontrer la somme 1 + q + ⋯ + qⁿ","description":"Démonstration à trous de 1 + q + ⋯ + qⁿ = (1 − qⁿ⁺¹)/(1 − q), q ≠ 1 : qS à compléter, S − qS, justification de la division par 1 − q","variations":[{"statement":"Soit $q$ un réel différent de $1$, $n$ un entier naturel et $S=1+q+q^2+\\cdots+q^n$.\n\nOn multiplie chaque terme de $S$ par $q$. Complète.\n\n$qS=q+q^2+\\cdots+q^n+?$","variables":[],"blanks":[{"expectedAnswer":"q^{n+1}"}],"correction":{"steps":["Multiplier par $q$ ajoute $1$ à chaque exposant : $1$ devient $q$, $q$ devient $q^2$, …, $q^n$ devient $q^{n+1}$.","Donc $qS=q+q^2+\\cdots+q^n+\\textcolor{{{color:primary.0}}}{q^{n+1}}$."]}},{"statement":"Soit $q$ un réel différent de $1$, $n$ un entier naturel et $S=1+q+q^2+\\cdots+q^n$.\n\nOn multiplie $S$ par $q$ :\n\n$$qS=q+q^2+\\cdots+q^n+q^{n+1}$$\n\npuis on soustrait membre à membre. Les termes $q$, $q^2$, …, $q^n$ se simplifient. Complète.\n\n$S-qS=?$","variables":[],"blanks":[{"expectedAnswer":"1-q^{n+1}"}],"correction":{"steps":["Les termes $q$, …, $q^n$ sont à la fois dans $S$ et dans $qS$ : ils disparaissent.","Il reste le premier terme de $S$, $1$, et le dernier terme de $qS$, $q^{n+1}$, avec le signe $-$.","Donc $S-qS=\\textcolor{{{color:primary.0}}}{1-q^{n+1}}$."]}},{"statement":"Soit $q$ un réel différent de $1$, $n$ un entier naturel et $S=1+q+q^2+\\cdots+q^n$.\n\nOn multiplie $S$ par $q$ :\n\n$$qS=q+q^2+\\cdots+q^n+q^{n+1}$$\n\npuis on soustrait membre à membre : $S-qS=1-q^{n+1}$, soit $S(1-q)=1-q^{n+1}$.\n\nOn en déduit $S=\\dfrac{1-q^{n+1}}{1-q}$ en divisant par $1-q$. Pourquoi cette division est-elle permise ?\n\n```choix\n- Car $q\\neq 1$, donc $1-q\\neq 0$.\n- Car $q\\neq 0$.\n- Car $q>0$.\n- Car $n\\neq 0$.\n```","variables":[],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["On ne peut diviser que par un nombre non nul.","Ici $q\\neq 1$, donc $\\textcolor{{{color:primary.0}}}{1-q\\neq 0}$ : $S=\\dfrac{1-q^{n+1}}{1-q}$.","Si $q=1$, la formule ne s'applique pas : $S=1+1+\\cdots+1=n+1$."]}}],"shared":{},"test_specs":[{"description":"qⁿ⁺¹","variationIndex":0,"variables":{},"answers":["q^{n+1}"],"expected":{"status":"correct"}},{"description":"Erreur : qⁿ","variationIndex":0,"variables":{},"answers":["q^n"],"expected":{"status":"incorrect"}},{"description":"Erreur : nq","variationIndex":0,"variables":{},"answers":["nq"],"expected":{"status":"incorrect"}},{"description":"1 − qⁿ⁺¹","variationIndex":1,"variables":{},"answers":["1-q^{n+1}"],"expected":{"status":"correct"}},{"description":"Écriture −qⁿ⁺¹ + 1","variationIndex":1,"variables":{},"answers":["-q^{n+1}+1"],"expected":{"status":"correct"}},{"description":"Erreur : 1 − qⁿ","variationIndex":1,"variables":{},"answers":["1-q^n"],"expected":{"status":"incorrect"}},{"description":"Erreur : 1 + qⁿ⁺¹","variationIndex":1,"variables":{},"answers":["1+q^{n+1}"],"expected":{"status":"incorrect"}},{"description":"Erreur : qⁿ⁺¹ − 1 (sens inversé)","variationIndex":1,"variables":{},"answers":["q^{n+1}-1"],"expected":{"status":"incorrect"}},{"description":"q ≠ 1","variationIndex":2,"variables":{},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : q ≠ 0","variationIndex":2,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : q > 0","variationIndex":2,"variables":{},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : n ≠ 0","variationIndex":2,"variables":{},"answers":["3"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
  $qdeme${"title":"Démontrer la somme 1 + q + ⋯ + qⁿ","description":"Démonstration à trous de 1 + q + ⋯ + qⁿ = (1 − qⁿ⁺¹)/(1 − q), q ≠ 1 : qS à compléter, S − qS, justification de la division par 1 − q","variations":[{"statement":"Soit $q$ un réel différent de $1$, $n$ un entier naturel et $S=1+q+q^2+\\cdots+q^n$.\n\nOn multiplie chaque terme de $S$ par $q$. Complète.\n\n$qS=q+q^2+\\cdots+q^n+?$","variables":[],"blanks":[{"expectedAnswer":"q^{n+1}"}],"correction":{"steps":["Multiplier par $q$ ajoute $1$ à chaque exposant : $1$ devient $q$, $q$ devient $q^2$, …, $q^n$ devient $q^{n+1}$.","Donc $qS=q+q^2+\\cdots+q^n+\\textcolor{{{color:primary.0}}}{q^{n+1}}$."]}},{"statement":"Soit $q$ un réel différent de $1$, $n$ un entier naturel et $S=1+q+q^2+\\cdots+q^n$.\n\nOn multiplie $S$ par $q$ :\n\n$$qS=q+q^2+\\cdots+q^n+q^{n+1}$$\n\npuis on soustrait membre à membre. Les termes $q$, $q^2$, …, $q^n$ se simplifient. Complète.\n\n$S-qS=?$","variables":[],"blanks":[{"expectedAnswer":"1-q^{n+1}"}],"correction":{"steps":["Les termes $q$, …, $q^n$ sont à la fois dans $S$ et dans $qS$ : ils disparaissent.","Il reste le premier terme de $S$, $1$, et le dernier terme de $qS$, $q^{n+1}$, avec le signe $-$.","Donc $S-qS=\\textcolor{{{color:primary.0}}}{1-q^{n+1}}$."]}},{"statement":"Soit $q$ un réel différent de $1$, $n$ un entier naturel et $S=1+q+q^2+\\cdots+q^n$.\n\nOn multiplie $S$ par $q$ :\n\n$$qS=q+q^2+\\cdots+q^n+q^{n+1}$$\n\npuis on soustrait membre à membre : $S-qS=1-q^{n+1}$, soit $S(1-q)=1-q^{n+1}$.\n\nOn en déduit $S=\\dfrac{1-q^{n+1}}{1-q}$ en divisant par $1-q$. Pourquoi cette division est-elle permise ?\n\n```choix\n- Car $q\\neq 1$, donc $1-q\\neq 0$.\n- Car $q\\neq 0$.\n- Car $q>0$.\n- Car $n\\neq 0$.\n```","variables":[],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["On ne peut diviser que par un nombre non nul.","Ici $q\\neq 1$, donc $\\textcolor{{{color:primary.0}}}{1-q\\neq 0}$ : $S=\\dfrac{1-q^{n+1}}{1-q}$.","Si $q=1$, la formule ne s'applique pas : $S=1+1+\\cdots+1=n+1$."]}},{"statement":"Soit $q$ un réel différent de $1$, $n$ un entier naturel et $S=1+q+q^2+\\cdots+q^n$. On démontre que $S=\\dfrac{1-q^{n+1}}{1-q}$.\n\nRemets les étapes de la démonstration dans l'ordre.\n\n```ranger\nsigne: aucun\n- On multiplie chaque terme de $S$ par $q$ : $qS=q+q^2+\\cdots+q^n+q^{n+1}$.\n- On soustrait : les termes $q$, …, $q^n$ se compensent, et $S-qS=1-q^{n+1}$.\n- Or $S-qS=(1-q)S$, donc $(1-q)S=1-q^{n+1}$.\n- Comme $q\\neq 1$, $1-q\\neq 0$ : $S=\\dfrac{1-q^{n+1}}{1-q}$.\n```","variables":[],"correction":{"steps":["$S$ et $qS$ ont les mêmes termes, sauf $1$ (dans $S$) et $q^{n+1}$ (dans $qS$) : leur différence vaut $1-q^{n+1}$.","On factorise par $S$, puis on divise par $1-q$, qui n'est pas nul : $\\textcolor{{{color:primary.0}}}{S=\\dfrac{1-q^{n+1}}{1-q}}$."]}}],"shared":{},"test_specs":[{"description":"qⁿ⁺¹","variationIndex":0,"variables":{},"answers":["q^{n+1}"],"expected":{"status":"correct"}},{"description":"Erreur : qⁿ","variationIndex":0,"variables":{},"answers":["q^n"],"expected":{"status":"incorrect"}},{"description":"Erreur : nq","variationIndex":0,"variables":{},"answers":["nq"],"expected":{"status":"incorrect"}},{"description":"1 − qⁿ⁺¹","variationIndex":1,"variables":{},"answers":["1-q^{n+1}"],"expected":{"status":"correct"}},{"description":"Écriture −qⁿ⁺¹ + 1","variationIndex":1,"variables":{},"answers":["-q^{n+1}+1"],"expected":{"status":"correct"}},{"description":"Erreur : 1 − qⁿ","variationIndex":1,"variables":{},"answers":["1-q^n"],"expected":{"status":"incorrect"}},{"description":"Erreur : 1 + qⁿ⁺¹","variationIndex":1,"variables":{},"answers":["1+q^{n+1}"],"expected":{"status":"incorrect"}},{"description":"Erreur : qⁿ⁺¹ − 1 (sens inversé)","variationIndex":1,"variables":{},"answers":["q^{n+1}-1"],"expected":{"status":"incorrect"}},{"description":"q ≠ 1","variationIndex":2,"variables":{},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : q ≠ 0","variationIndex":2,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : q > 0","variationIndex":2,"variables":{},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : n ≠ 0","variationIndex":2,"variables":{},"answers":["3"],"expected":{"status":"incorrect"}},{"description":"Étapes dans l’ordre","variationIndex":3,"variables":{},"answers":["3","0","1","2"],"expected":{"status":"correct"}},{"description":"Erreur : deuxième et troisième étapes échangées","variationIndex":3,"variables":{},"answers":["3","1","0","2"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
  null, null, null);
insert into _qdeme_modeles values ('dbdf02be-9dbe-4b9a-97ff-3ab197135785', $qdeme$Géométrie$qdeme$, $qdeme$Produit scalaire$qdeme$, $qdeme$lieux de points$qdeme$, array['1_SPE'], 'published',
  $qdeme${"title":"Démontrer l'ensemble des points M tels que MA·MB = 0","description":"Démonstration à trous, par le milieu I de [AB] : MA·MB = MI² − IA², MI pour AB tiré, conclusion (le cercle de diamètre [AB])","variations":[{"statement":"Soit $A$ et $B$ deux points distincts, et $I$ le milieu de $[AB]$. On cherche l'ensemble des points $M$ du plan tels que $\\overrightarrow{MA}\\cdot\\overrightarrow{MB}=0$.\n\nPar la relation de Chasles, $\\overrightarrow{MA}\\cdot\\overrightarrow{MB}=\\left(\\overrightarrow{MI}+\\overrightarrow{IA}\\right)\\cdot\\left(\\overrightarrow{MI}+\\overrightarrow{IB}\\right)$. Comme $I$ est le milieu de $[AB]$, $\\overrightarrow{IB}=-\\overrightarrow{IA}$. Que vaut ce produit scalaire ?\n\n```choix\n- $MI^2-IA^2$\n- $MI^2+IA^2$\n- $\\left(MI-IA\\right)^2$\n- $MI^2-2\\,\\overrightarrow{MI}\\cdot\\overrightarrow{IA}$\n```","variables":[],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["$\\left(\\overrightarrow{MI}+\\overrightarrow{IA}\\right)\\cdot\\left(\\overrightarrow{MI}-\\overrightarrow{IA}\\right)$ se développe comme $(a+b)(a-b)=a^2-b^2$.","Les termes $\\overrightarrow{MI}\\cdot\\overrightarrow{IA}$ se compensent : il reste $\\textcolor{{{color:primary.0}}}{MI^2-IA^2}$."]}},{"statement":"Soit $A$ et $B$ deux points distincts, et $I$ le milieu de $[AB]$. On cherche l'ensemble des points $M$ du plan tels que $\\overrightarrow{MA}\\cdot\\overrightarrow{MB}=0$.\n\nEn introduisant $I$ par la relation de Chasles, et comme $\\overrightarrow{IB}=-\\overrightarrow{IA}$, on obtient $\\overrightarrow{MA}\\cdot\\overrightarrow{MB}=MI^2-IA^2$.\n\nOn prend $AB={{eval:2*d}}$. Le point $M$ vérifie $\\overrightarrow{MA}\\cdot\\overrightarrow{MB}=0$ si et seulement si $MI^2=IA^2$, c'est-à-dire $MI=IA$ (des longueurs sont positives). Complète.\n\n$MI=?$","variables":[{"name":"d","expression":"2..9"}],"blanks":[{"expectedAnswer":"{{eval:d}}"}],"correction":{"steps":["$I$ est le milieu de $[AB]$ : $IA=\\dfrac{AB}{2}=\\dfrac{{{eval:2*d}}}{2}={{eval:d}}$.","Donc $MI=\\textcolor{{{color:primary.0}}}{{{eval:d}}}$ : $M$ est à la distance ${{eval:d}}$ de $I$."]}},{"statement":"Soit $A$ et $B$ deux points distincts, et $I$ le milieu de $[AB]$. On cherche l'ensemble des points $M$ du plan tels que $\\overrightarrow{MA}\\cdot\\overrightarrow{MB}=0$.\n\nEn introduisant $I$ par la relation de Chasles, et comme $\\overrightarrow{IB}=-\\overrightarrow{IA}$, on obtient $\\overrightarrow{MA}\\cdot\\overrightarrow{MB}=MI^2-IA^2$.\n\nDonc $\\overrightarrow{MA}\\cdot\\overrightarrow{MB}=0$ si et seulement si $MI=IA=\\dfrac{AB}{2}$. Quel est l'ensemble des points $M$ cherché ?\n\n```choix\n- Le cercle de diamètre $[AB]$.\n- La médiatrice de $[AB]$.\n- Le cercle de centre $A$ et de rayon $AB$.\n- Le seul point $I$.\n```","variables":[],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["Les points $M$ tels que $MI=\\dfrac{AB}{2}$ forment le cercle de centre $I$ et de rayon $\\dfrac{AB}{2}$.","Son centre est le milieu de $[AB]$ et son rayon la moitié de $AB$ : c'est le **cercle de diamètre $[AB]$**.","La médiatrice de $[AB]$ est l'ensemble des points $M$ tels que $MA=MB$."]}}],"shared":{},"test_specs":[{"description":"MI² − IA²","variationIndex":0,"variables":{},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : MI² + IA²","variationIndex":0,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : (MI − IA)²","variationIndex":0,"variables":{},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : MI² − 2MI·IA","variationIndex":0,"variables":{},"answers":["3"],"expected":{"status":"incorrect"}},{"description":"3 (AB = 6)","variationIndex":1,"variables":{"d":"3"},"answers":["3"],"expected":{"status":"correct"}},{"description":"Erreur : 6 (AB)","variationIndex":1,"variables":{"d":"3"},"answers":["6"],"expected":{"status":"incorrect"}},{"description":"Erreur : 9 (IA²)","variationIndex":1,"variables":{"d":"3"},"answers":["9"],"expected":{"status":"incorrect"}},{"description":"Erreur : 0","variationIndex":1,"variables":{"d":"3"},"answers":["0"],"expected":{"status":"incorrect"}},{"description":"cercle de diamètre [AB]","variationIndex":2,"variables":{},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : médiatrice","variationIndex":2,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : cercle de centre A","variationIndex":2,"variables":{},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : point I","variationIndex":2,"variables":{},"answers":["3"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
  $qdeme${"title":"Démontrer l'ensemble des points M tels que MA·MB = 0","description":"Démonstration à trous, par le milieu I de [AB] : MA·MB = MI² − IA², MI pour AB tiré, conclusion (le cercle de diamètre [AB])","variations":[{"statement":"Soit $A$ et $B$ deux points distincts, et $I$ le milieu de $[AB]$. On cherche l'ensemble des points $M$ du plan tels que $\\overrightarrow{MA}\\cdot\\overrightarrow{MB}=0$.\n\nPar la relation de Chasles, $\\overrightarrow{MA}\\cdot\\overrightarrow{MB}=\\left(\\overrightarrow{MI}+\\overrightarrow{IA}\\right)\\cdot\\left(\\overrightarrow{MI}+\\overrightarrow{IB}\\right)$. Comme $I$ est le milieu de $[AB]$, $\\overrightarrow{IB}=-\\overrightarrow{IA}$. Que vaut ce produit scalaire ?\n\n```choix\n- $MI^2-IA^2$\n- $MI^2+IA^2$\n- $\\left(MI-IA\\right)^2$\n- $MI^2-2\\,\\overrightarrow{MI}\\cdot\\overrightarrow{IA}$\n```","variables":[],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["$\\left(\\overrightarrow{MI}+\\overrightarrow{IA}\\right)\\cdot\\left(\\overrightarrow{MI}-\\overrightarrow{IA}\\right)$ se développe comme $(a+b)(a-b)=a^2-b^2$.","Les termes $\\overrightarrow{MI}\\cdot\\overrightarrow{IA}$ se compensent : il reste $\\textcolor{{{color:primary.0}}}{MI^2-IA^2}$."]}},{"statement":"Soit $A$ et $B$ deux points distincts, et $I$ le milieu de $[AB]$. On cherche l'ensemble des points $M$ du plan tels que $\\overrightarrow{MA}\\cdot\\overrightarrow{MB}=0$.\n\nEn introduisant $I$ par la relation de Chasles, et comme $\\overrightarrow{IB}=-\\overrightarrow{IA}$, on obtient $\\overrightarrow{MA}\\cdot\\overrightarrow{MB}=MI^2-IA^2$.\n\nOn prend $AB={{eval:2*d}}$. Le point $M$ vérifie $\\overrightarrow{MA}\\cdot\\overrightarrow{MB}=0$ si et seulement si $MI^2=IA^2$, c'est-à-dire $MI=IA$ (des longueurs sont positives). Complète.\n\n$MI=?$","variables":[{"name":"d","expression":"2..9"}],"blanks":[{"expectedAnswer":"{{eval:d}}"}],"correction":{"steps":["$I$ est le milieu de $[AB]$ : $IA=\\dfrac{AB}{2}=\\dfrac{{{eval:2*d}}}{2}={{eval:d}}$.","Donc $MI=\\textcolor{{{color:primary.0}}}{{{eval:d}}}$ : $M$ est à la distance ${{eval:d}}$ de $I$."]}},{"statement":"Soit $A$ et $B$ deux points distincts, et $I$ le milieu de $[AB]$. On cherche l'ensemble des points $M$ du plan tels que $\\overrightarrow{MA}\\cdot\\overrightarrow{MB}=0$.\n\nEn introduisant $I$ par la relation de Chasles, et comme $\\overrightarrow{IB}=-\\overrightarrow{IA}$, on obtient $\\overrightarrow{MA}\\cdot\\overrightarrow{MB}=MI^2-IA^2$.\n\nDonc $\\overrightarrow{MA}\\cdot\\overrightarrow{MB}=0$ si et seulement si $MI=IA=\\dfrac{AB}{2}$. Quel est l'ensemble des points $M$ cherché ?\n\n```choix\n- Le cercle de diamètre $[AB]$.\n- La médiatrice de $[AB]$.\n- Le cercle de centre $A$ et de rayon $AB$.\n- Le seul point $I$.\n```","variables":[],"blanks":[{"expectedAnswer":"0"}],"correction":{"steps":["Les points $M$ tels que $MI=\\dfrac{AB}{2}$ forment le cercle de centre $I$ et de rayon $\\dfrac{AB}{2}$.","Son centre est le milieu de $[AB]$ et son rayon la moitié de $AB$ : c'est le **cercle de diamètre $[AB]$**.","La médiatrice de $[AB]$ est l'ensemble des points $M$ tels que $MA=MB$."]}},{"statement":"Soit $A$ et $B$ deux points distincts, et $I$ le milieu de $[AB]$. On démontre que l'ensemble des points $M$ du plan tels que $\\overrightarrow{MA}\\cdot\\overrightarrow{MB}=0$ est le cercle de diamètre $[AB]$.\n\nRemets les étapes de la démonstration dans l'ordre.\n\n```ranger\nsigne: aucun\n- Par la relation de Chasles, $\\overrightarrow{MA}\\cdot\\overrightarrow{MB}=\\left(\\overrightarrow{MI}+\\overrightarrow{IA}\\right)\\cdot\\left(\\overrightarrow{MI}+\\overrightarrow{IB}\\right)$.\n- Comme $\\overrightarrow{IB}=-\\overrightarrow{IA}$, $\\overrightarrow{MA}\\cdot\\overrightarrow{MB}=\\left(\\overrightarrow{MI}+\\overrightarrow{IA}\\right)\\cdot\\left(\\overrightarrow{MI}-\\overrightarrow{IA}\\right)=MI^2-IA^2$.\n- Donc $\\overrightarrow{MA}\\cdot\\overrightarrow{MB}=0$ équivaut à $MI^2=IA^2$, soit, les longueurs étant positives, $MI=IA=\\dfrac{AB}{2}$.\n- L'ensemble cherché est le cercle de centre $I$ et de rayon $\\dfrac{AB}{2}$ : le cercle de diamètre $[AB]$.\n```","variables":[],"correction":{"steps":["On passe par le milieu $I$ : le produit scalaire devient $MI^2-IA^2$.","Il est nul quand $MI=\\dfrac{AB}{2}$ : $M$ décrit $\\textcolor{{{color:primary.0}}}{\\text{le cercle de diamètre }[AB]}$."]}}],"shared":{},"test_specs":[{"description":"MI² − IA²","variationIndex":0,"variables":{},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : MI² + IA²","variationIndex":0,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : (MI − IA)²","variationIndex":0,"variables":{},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : MI² − 2MI·IA","variationIndex":0,"variables":{},"answers":["3"],"expected":{"status":"incorrect"}},{"description":"3 (AB = 6)","variationIndex":1,"variables":{"d":"3"},"answers":["3"],"expected":{"status":"correct"}},{"description":"Erreur : 6 (AB)","variationIndex":1,"variables":{"d":"3"},"answers":["6"],"expected":{"status":"incorrect"}},{"description":"Erreur : 9 (IA²)","variationIndex":1,"variables":{"d":"3"},"answers":["9"],"expected":{"status":"incorrect"}},{"description":"Erreur : 0","variationIndex":1,"variables":{"d":"3"},"answers":["0"],"expected":{"status":"incorrect"}},{"description":"cercle de diamètre [AB]","variationIndex":2,"variables":{},"answers":["0"],"expected":{"status":"correct"}},{"description":"Erreur : médiatrice","variationIndex":2,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : cercle de centre A","variationIndex":2,"variables":{},"answers":["2"],"expected":{"status":"incorrect"}},{"description":"Erreur : point I","variationIndex":2,"variables":{},"answers":["3"],"expected":{"status":"incorrect"}},{"description":"Étapes dans l’ordre","variationIndex":3,"variables":{},"answers":["3","0","1","2"],"expected":{"status":"correct"}},{"description":"Erreur : deuxième et troisième étapes échangées","variationIndex":3,"variables":{},"answers":["3","1","0","2"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
  null, null, null);
insert into _qdeme_modeles values ('e2908d60-2360-453c-a6e2-5c0318d8b9b2', $qdeme$Fonctions$qdeme$, $qdeme$Dérivation$qdeme$, $qdeme$fonctions dérivées$qdeme$, array['1_SPE'], 'published',
  $qdeme${"title":"Démontrer la dérivée de la fonction inverse","description":"Démonstration à trous de (1/x)′ = −1/x² par le taux de variation entre a et a + h : numérateur −h, taux −1/(a(a + h)), limite −1/a²","variations":[{"statement":"Soit $f$ la fonction inverse, définie sur $]-\\infty\\,;0[\\,\\cup\\,]0\\,;+\\infty[$ par $f(x)=\\dfrac{1}{x}$, et $a$ un réel non nul. Pour $h\\neq 0$ tel que $a+h\\neq 0$, on calcule le taux de variation de $f$ entre $a$ et $a+h$.\n\nOn réduit au même dénominateur. Complète.\n\n$f(a+h)-f(a)=\\dfrac{1}{a+h}-\\dfrac{1}{a}=\\dfrac{?}{a(a+h)}$","variables":[],"blanks":[{"expectedAnswer":"-h"}],"correction":{"steps":["$\\dfrac{1}{a+h}=\\dfrac{a}{a(a+h)}$ et $\\dfrac{1}{a}=\\dfrac{a+h}{a(a+h)}$.","Le numérateur vaut $a-(a+h)=\\textcolor{{{color:primary.0}}}{-h}$."]}},{"statement":"Soit $f$ la fonction inverse, définie sur $]-\\infty\\,;0[\\,\\cup\\,]0\\,;+\\infty[$ par $f(x)=\\dfrac{1}{x}$, et $a$ un réel non nul. Pour $h\\neq 0$ tel que $a+h\\neq 0$, on calcule le taux de variation de $f$ entre $a$ et $a+h$.\n\nComme $f(a+h)-f(a)=\\dfrac{-h}{a(a+h)}$, on divise par $h$. Complète.\n\n$\\dfrac{f(a+h)-f(a)}{h}=?$","variables":[],"blanks":[{"expectedAnswer":"-\\frac{1}{a(a+h)}","requiredForm":{"pattern":"u"}}],"correction":{"steps":["Diviser par $h$, c'est multiplier par $\\dfrac{1}{h}$ : $\\dfrac{-h}{a(a+h)}\\times\\dfrac{1}{h}$.","Comme $h\\neq 0$, on simplifie par $h$ : le taux vaut $\\textcolor{{{color:primary.0}}}{-\\dfrac{1}{a(a+h)}}$."]}},{"statement":"Soit $f$ la fonction inverse, définie sur $]-\\infty\\,;0[\\,\\cup\\,]0\\,;+\\infty[$ par $f(x)=\\dfrac{1}{x}$, et $a$ un réel non nul. Pour $h\\neq 0$ tel que $a+h\\neq 0$, on calcule le taux de variation de $f$ entre $a$ et $a+h$.\n\nLe taux vaut $-\\dfrac{1}{a(a+h)}$. Quand $h$ tend vers $0$, $a(a+h)$ tend vers $a\\times a$. Complète.\n\n$f'(a)=?$","variables":[],"blanks":[{"expectedAnswer":"-\\frac{1}{a^2}","requiredForm":{"pattern":"u"}}],"correction":{"steps":["Quand $h$ tend vers $0$, $a+h$ tend vers $a$, donc $a(a+h)$ tend vers $a^2$, qui n'est pas nul.","Le taux tend donc vers $\\textcolor{{{color:primary.0}}}{-\\dfrac{1}{a^2}}$ : $f$ est dérivable en $a$ et $f'(a)=-\\dfrac{1}{a^2}$."]}}],"shared":{},"test_specs":[{"description":"−h","variationIndex":0,"variables":{},"answers":["-h"],"expected":{"status":"correct"}},{"description":"Erreur : h (soustraction inversée)","variationIndex":0,"variables":{},"answers":["h"],"expected":{"status":"incorrect"}},{"description":"Erreur : 1","variationIndex":0,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : −1","variationIndex":0,"variables":{},"answers":["-1"],"expected":{"status":"incorrect"}},{"description":"−1/(a(a + h))","variationIndex":1,"variables":{},"answers":["-\\frac{1}{a(a+h)}"],"expected":{"status":"correct"}},{"description":"Forme (−1)/(a(a + h)) : signe à sortir","variationIndex":1,"variables":{},"answers":["\\frac{-1}{a(a+h)}"],"expected":{"status":"unoptimal_form","constraintViolations":["signs"]}},{"description":"Écriture −1/(a² + ah)","variationIndex":1,"variables":{},"answers":["-\\frac{1}{a^2+ah}"],"expected":{"status":"correct"}},{"description":"Erreur : −1/(a(2a + h))","variationIndex":1,"variables":{},"answers":["-\\frac{1}{a(2a+h)}"],"expected":{"status":"incorrect"}},{"description":"Erreur : 1/(a(a + h))","variationIndex":1,"variables":{},"answers":["\\frac{1}{a(a+h)}"],"expected":{"status":"incorrect"}},{"description":"Erreur : −h/(a(a + h)) (pas divisé)","variationIndex":1,"variables":{},"answers":["\\frac{-h}{a(a+h)}"],"expected":{"status":"incorrect"}},{"description":"Erreur : −1/a² (limite au lieu du taux)","variationIndex":1,"variables":{},"answers":["-\\frac{1}{a^2}"],"expected":{"status":"incorrect"}},{"description":"−1/a²","variationIndex":2,"variables":{},"answers":["-\\frac{1}{a^2}"],"expected":{"status":"correct"}},{"description":"Forme (−1)/a² : signe à sortir","variationIndex":2,"variables":{},"answers":["\\frac{-1}{a^2}"],"expected":{"status":"unoptimal_form","constraintViolations":["signs"]}},{"description":"Erreur : 1/a²","variationIndex":2,"variables":{},"answers":["\\frac{1}{a^2}"],"expected":{"status":"incorrect"}},{"description":"Erreur : −1/a","variationIndex":2,"variables":{},"answers":["-\\frac{1}{a}"],"expected":{"status":"incorrect"}},{"description":"Erreur : −1/(2a)","variationIndex":2,"variables":{},"answers":["-\\frac{1}{2a}"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
  $qdeme${"title":"Démontrer la dérivée de la fonction inverse","description":"Démonstration à trous de (1/x)′ = −1/x² par le taux de variation entre a et a + h : numérateur −h, taux −1/(a(a + h)), limite −1/a²","variations":[{"statement":"Soit $f$ la fonction inverse, définie sur $]-\\infty\\,;0[\\,\\cup\\,]0\\,;+\\infty[$ par $f(x)=\\dfrac{1}{x}$, et $a$ un réel non nul. Pour $h\\neq 0$ tel que $a+h\\neq 0$, on calcule le taux de variation de $f$ entre $a$ et $a+h$.\n\nOn réduit au même dénominateur. Complète.\n\n$f(a+h)-f(a)=\\dfrac{1}{a+h}-\\dfrac{1}{a}=\\dfrac{?}{a(a+h)}$","variables":[],"blanks":[{"expectedAnswer":"-h"}],"correction":{"steps":["$\\dfrac{1}{a+h}=\\dfrac{a}{a(a+h)}$ et $\\dfrac{1}{a}=\\dfrac{a+h}{a(a+h)}$.","Le numérateur vaut $a-(a+h)=\\textcolor{{{color:primary.0}}}{-h}$."]}},{"statement":"Soit $f$ la fonction inverse, définie sur $]-\\infty\\,;0[\\,\\cup\\,]0\\,;+\\infty[$ par $f(x)=\\dfrac{1}{x}$, et $a$ un réel non nul. Pour $h\\neq 0$ tel que $a+h\\neq 0$, on calcule le taux de variation de $f$ entre $a$ et $a+h$.\n\nComme $f(a+h)-f(a)=\\dfrac{-h}{a(a+h)}$, on divise par $h$. Complète.\n\n$\\dfrac{f(a+h)-f(a)}{h}=?$","variables":[],"blanks":[{"expectedAnswer":"-\\frac{1}{a(a+h)}","requiredForm":{"pattern":"u"}}],"correction":{"steps":["Diviser par $h$, c'est multiplier par $\\dfrac{1}{h}$ : $\\dfrac{-h}{a(a+h)}\\times\\dfrac{1}{h}$.","Comme $h\\neq 0$, on simplifie par $h$ : le taux vaut $\\textcolor{{{color:primary.0}}}{-\\dfrac{1}{a(a+h)}}$."]}},{"statement":"Soit $f$ la fonction inverse, définie sur $]-\\infty\\,;0[\\,\\cup\\,]0\\,;+\\infty[$ par $f(x)=\\dfrac{1}{x}$, et $a$ un réel non nul. Pour $h\\neq 0$ tel que $a+h\\neq 0$, on calcule le taux de variation de $f$ entre $a$ et $a+h$.\n\nLe taux vaut $-\\dfrac{1}{a(a+h)}$. Quand $h$ tend vers $0$, $a(a+h)$ tend vers $a\\times a$. Complète.\n\n$f'(a)=?$","variables":[],"blanks":[{"expectedAnswer":"-\\frac{1}{a^2}","requiredForm":{"pattern":"u"}}],"correction":{"steps":["Quand $h$ tend vers $0$, $a+h$ tend vers $a$, donc $a(a+h)$ tend vers $a^2$, qui n'est pas nul.","Le taux tend donc vers $\\textcolor{{{color:primary.0}}}{-\\dfrac{1}{a^2}}$ : $f$ est dérivable en $a$ et $f'(a)=-\\dfrac{1}{a^2}$."]}},{"statement":"Soit $f$ la fonction inverse, définie sur $]-\\infty\\,;0[\\,\\cup\\,]0\\,;+\\infty[$ par $f(x)=\\dfrac{1}{x}$, $a$ un réel non nul et $h$ un réel non nul tel que $a+h\\neq 0$. On démontre que $f'(a)=-\\dfrac{1}{a^2}$.\n\nRemets les étapes de la démonstration dans l'ordre.\n\n```ranger\nsigne: aucun\n- $f(a+h)-f(a)=\\dfrac{1}{a+h}-\\dfrac{1}{a}=\\dfrac{-h}{a(a+h)}$.\n- Le taux de variation vaut $\\dfrac{f(a+h)-f(a)}{h}=-\\dfrac{1}{a(a+h)}$.\n- Quand $h$ tend vers $0$, $a(a+h)$ tend vers $a^2$, non nul : le taux tend vers $-\\dfrac{1}{a^2}$.\n- Donc $f$ est dérivable en $a$ et $f'(a)=-\\dfrac{1}{a^2}$.\n```","variables":[],"correction":{"steps":["On réduit au même dénominateur, on simplifie le taux par $h$ (non nul), puis on fait tendre $h$ vers $0$.","Le taux tend vers $-\\dfrac{1}{a^2}$ : $\\textcolor{{{color:primary.0}}}{f'(a)=-\\dfrac{1}{a^2}}$."]}}],"shared":{},"test_specs":[{"description":"−h","variationIndex":0,"variables":{},"answers":["-h"],"expected":{"status":"correct"}},{"description":"Erreur : h (soustraction inversée)","variationIndex":0,"variables":{},"answers":["h"],"expected":{"status":"incorrect"}},{"description":"Erreur : 1","variationIndex":0,"variables":{},"answers":["1"],"expected":{"status":"incorrect"}},{"description":"Erreur : −1","variationIndex":0,"variables":{},"answers":["-1"],"expected":{"status":"incorrect"}},{"description":"−1/(a(a + h))","variationIndex":1,"variables":{},"answers":["-\\frac{1}{a(a+h)}"],"expected":{"status":"correct"}},{"description":"Forme (−1)/(a(a + h)) : signe à sortir","variationIndex":1,"variables":{},"answers":["\\frac{-1}{a(a+h)}"],"expected":{"status":"unoptimal_form","constraintViolations":["signs"]}},{"description":"Écriture −1/(a² + ah)","variationIndex":1,"variables":{},"answers":["-\\frac{1}{a^2+ah}"],"expected":{"status":"correct"}},{"description":"Erreur : −1/(a(2a + h))","variationIndex":1,"variables":{},"answers":["-\\frac{1}{a(2a+h)}"],"expected":{"status":"incorrect"}},{"description":"Erreur : 1/(a(a + h))","variationIndex":1,"variables":{},"answers":["\\frac{1}{a(a+h)}"],"expected":{"status":"incorrect"}},{"description":"Erreur : −h/(a(a + h)) (pas divisé)","variationIndex":1,"variables":{},"answers":["\\frac{-h}{a(a+h)}"],"expected":{"status":"incorrect"}},{"description":"Erreur : −1/a² (limite au lieu du taux)","variationIndex":1,"variables":{},"answers":["-\\frac{1}{a^2}"],"expected":{"status":"incorrect"}},{"description":"−1/a²","variationIndex":2,"variables":{},"answers":["-\\frac{1}{a^2}"],"expected":{"status":"correct"}},{"description":"Forme (−1)/a² : signe à sortir","variationIndex":2,"variables":{},"answers":["\\frac{-1}{a^2}"],"expected":{"status":"unoptimal_form","constraintViolations":["signs"]}},{"description":"Erreur : 1/a²","variationIndex":2,"variables":{},"answers":["\\frac{1}{a^2}"],"expected":{"status":"incorrect"}},{"description":"Erreur : −1/a","variationIndex":2,"variables":{},"answers":["-\\frac{1}{a}"],"expected":{"status":"incorrect"}},{"description":"Erreur : −1/(2a)","variationIndex":2,"variables":{},"answers":["-\\frac{1}{2a}"],"expected":{"status":"incorrect"}},{"description":"Étapes dans l’ordre","variationIndex":3,"variables":{},"answers":["3","0","1","2"],"expected":{"status":"correct"}},{"description":"Erreur : deuxième et troisième étapes échangées","variationIndex":3,"variables":{},"answers":["3","1","0","2"],"expected":{"status":"incorrect"}}]}$qdeme$::jsonb,
