  ('9e377c97-6940-48c9-9442-d64f05cb9a94', '1_SPE', '1SPE-275', true),
  ('a81c4c9f-7a25-48a4-89c4-d48cadf0fa1b', '1_SPE', '1SPE-232', true),
  ('acaeb02a-e934-43b6-99bc-46bb1ffb4f0f', '1_SPE', '1SPE-233', true),
  ('b05ec37a-3e3a-4a98-bd32-635636b84281', '1_SPE', '1SPE-277', true),
  ('b554a47f-1b2e-4530-a979-44d785890adf', '1_SPE', '1SPE-235', true),
